function claimSectionSlug(value: string): string {
  const slug = value.normalize("NFKC").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-+|-+$/gu, "").slice(0, 96);
  return slug || "section";
}

function splitClaimSentences(paragraph: string): string[] {
  const sentences: string[] = [];
  let start = 0;
  for (let index = 0; index < paragraph.length; index += 1) {
    if (![".", "?", "!", "。", "？", "！"].includes(paragraph[index])) continue;
    let end = index + 1;
    while (end < paragraph.length && ["\"", "'", "”", "’", ")", "]", "}"].includes(paragraph[end])) end += 1;
    if (end < paragraph.length && !/\s/u.test(paragraph[end])) continue;
    const sentence = paragraph.slice(start, end).trim();
    if (sentence) sentences.push(sentence);
    while (end < paragraph.length && /\s/u.test(paragraph[end])) end += 1;
    start = end;
    index = end - 1;
  }
  const remainder = paragraph.slice(start).trim();
  if (remainder) sentences.push(remainder);
  return sentences;
}

function canonicalManuscriptSentences(markdown: string): ScienceCanonicalManuscriptSentence[] {
  const result: ScienceCanonicalManuscriptSentence[] = [];
  let sectionOrdinal = 0;
  let sectionId = "main-0";
  let paragraphOrdinal = 0;
  let paragraph: string[] = [];
  let inFence = false;
  const flush = (): void => {
    const text = paragraph.join("\n").trim();
    paragraph = [];
    if (!text) return;
    const sentences = splitClaimSentences(text);
    let sentenceOrdinal = 0;
    for (const sentence of sentences) {
      for (let offset = 0; offset < sentence.length; offset += CLAIM_SENTENCE_MAX_CODE_UNITS) {
        const chunk = sentence.slice(offset, offset + CLAIM_SENTENCE_MAX_CODE_UNITS);
        result.push({ sectionId, sectionOrdinal, paragraphOrdinal, sentenceOrdinal, text: chunk, textSha256: scienceClaimLedgerTextSha256(chunk) });
        sentenceOrdinal += 1;
      }
    }
    paragraphOrdinal += 1;
  };
  for (const line of markdown.replace(/\r\n?/gu, "\n").split("\n")) {
    if (/^\s*(```|~~~)/u.test(line)) {
      flush();
      inFence = !inFence;
      continue;
    }
    if (inFence) { paragraph.push(line); continue; }
    const heading = /^#{1,6}\s+(.+?)\s*$/u.exec(line);
    if (heading) {
      flush();
      sectionOrdinal += 1;
      sectionId = `${claimSectionSlug(heading[1])}-${sectionOrdinal}`;
      paragraphOrdinal = 0;
      paragraph.push(heading[1]);
      flush();
      continue;
    }
    if (!line.trim()) flush();
    else paragraph.push(line);
  }
  flush();
  return result;
}

function escapeJsonPointerSegment(value: string): string {
  return value.replace(/~/g, "~0").replace(/\//g, "~1");
}

function artifactDiffCategory(rendererId: ScienceRendererId, pointer: string): ScienceArtifactStructuralChange["category"] {
  if (rendererId === "agentlas.ketcher") {
    if (/\/atoms(?:\/|$)/.test(pointer)) return "atom";
    if (/\/bonds(?:\/|$)/.test(pointer)) return "bond";
    if (/\/(location|stereoFlagPosition)(?:\/|$)/.test(pointer)) return "layout";
    return "document";
  }
  if (rendererId === "agentlas.vega") {
    if (/^\/data(?:\/|$)/.test(pointer)) return "data";
    if (/\/transform(?:\/|$)/.test(pointer)) return "transform";
    if (/^\/scales(?:\/|$)/.test(pointer)) return "scale";
    if (/^\/(axes|legends)(?:\/|$)/.test(pointer)) return "axis";
    if (/^\/marks(?:\/|$)/.test(pointer)) return "mark";
    if (/^\/(width|height|padding|background|autosize)(?:\/|$)/.test(pointer)) return "layout";
    if (/^\/(config|style)(?:\/|$)/.test(pointer)) return "config";
    if (/^\/\$schema$/.test(pointer)) return "metadata";
    return "other";
  }
  if (/^\/(representation|colorTheme)$/.test(pointer)) return "representation";
  if (/^\/structure(?:\/|$)/.test(pointer)) return "structure";
  return "other";
}

interface ArtifactStructuralDiffState {
  rendererId: ScienceRendererId;
  count: number;
  changes: ScienceArtifactStructuralChange[];
  limit: number;
  categoryCounts: Record<string, number>;
}

function collectArtifactStructuralChanges(before: unknown, after: unknown, state: ArtifactStructuralDiffState, pointer = "", depth = 0): void {
  if (depth > 64) throw new Error("science-artifact-diff-too-complex");
  if (Object.is(before, after)) return;
  const beforeArray = Array.isArray(before);
  const afterArray = Array.isArray(after);
  const beforeRecord = Boolean(before) && typeof before === "object" && !beforeArray;
  const afterRecord = Boolean(after) && typeof after === "object" && !afterArray;
  if (beforeArray && afterArray) {
    const maximum = Math.max(before.length, after.length);
    for (let index = 0; index < maximum; index += 1) {
      collectArtifactStructuralChanges(before[index], after[index], state, `${pointer}/${index}`, depth + 1);
    }
    return;
  }
  if (beforeRecord && afterRecord) {
    const beforeObject = before as Record<string, unknown>;
    const afterObject = after as Record<string, unknown>;
    const keys = [...new Set([...Object.keys(beforeObject), ...Object.keys(afterObject)])].sort();
    for (const key of keys) {
      collectArtifactStructuralChanges(beforeObject[key], afterObject[key], state, `${pointer}/${escapeJsonPointerSegment(key)}`, depth + 1);
    }
    return;
  }
  state.count += 1;
  const pathValue = pointer || "/";
  const category = artifactDiffCategory(state.rendererId, pathValue);
  state.categoryCounts[category] = (state.categoryCounts[category] ?? 0) + 1;
  if (state.changes.length >= state.limit) return;
  const beforeMissing = before === undefined;
  const afterMissing = after === undefined;
  if (pathValue.length > 2_048) throw new Error("science-artifact-diff-path-too-long");
  state.changes.push({
    path: pathValue,
    kind: beforeMissing ? "added" : afterMissing ? "removed" : "replaced",
    category,
    beforeSha256: beforeMissing ? null : sha256Json(before),
    afterSha256: afterMissing ? null : sha256Json(after),
  });
}

function parseCanonicalKet(value: string): Record<string, unknown> {
  let parsed: unknown;
  try { parsed = JSON.parse(value); } catch { throw new Error("science-chemistry-ket-json-invalid"); }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("science-chemistry-ket-json-invalid");
  let nodes = 0;
  const visit = (entry: unknown, depth: number): void => {
    if (++nodes > 100_000 || depth > 64) throw new Error("science-chemistry-ket-too-complex");
    if (!entry || typeof entry !== "object") return;
    if (Array.isArray(entry)) {
      for (const item of entry) visit(item, depth + 1);
      return;
    }
    for (const [key, item] of Object.entries(entry as Record<string, unknown>)) {
      if (["__proto__", "prototype", "constructor"].includes(key)) throw new Error("science-chemistry-ket-json-invalid");
      visit(item, depth + 1);
    }
  };
  visit(parsed, 0);
  return canonicalValue(parsed) as Record<string, unknown>;
}

function safeSha256(value: unknown, field: string): string {
  const normalized = String(value ?? "").toLowerCase();
  if (!SHA256_RE.test(normalized)) throw new Error(`science-${field}-invalid`);
  return normalized;
}

function safePrefixedSha256(value: unknown, field: string): string {
  const normalized = String(value ?? "").toLowerCase();
  if (!/^sha256:[a-f0-9]{64}$/u.test(normalized)) throw new Error(`science-${field}-invalid`);
  return normalized;
}

function normalizeLoopCriterionVerifier(value: unknown): ScienceLoopCriterionVerifier {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || !hasExactKeys(value as Record<string, unknown>, ["method", "agentId", "agentSlug", "packageVersion", "packageDigest", "systemPromptSha256", "invocationRunId"])) {
    throw new Error("science-loop-criterion-verifier-invalid");
  }
  const record = value as Record<string, unknown>;
  if (record.method !== "research-director-attestation" || !UUID_RE.test(String(record.invocationRunId ?? ""))) {
    throw new Error("science-loop-criterion-verifier-invalid");
  }
  return {
    method: "research-director-attestation",
    agentId: safeText(record.agentId, 240, "loop-criterion-verifier-agent-id"),
    agentSlug: safeText(record.agentSlug, 240, "loop-criterion-verifier-agent-slug"),
    packageVersion: safeText(record.packageVersion, 80, "loop-criterion-verifier-package-version"),
    packageDigest: safePrefixedSha256(record.packageDigest, "loop-criterion-verifier-package-digest"),
    systemPromptSha256: safeSha256(record.systemPromptSha256, "loop-criterion-verifier-prompt-sha256"),
    invocationRunId: String(record.invocationRunId),
  };
}

function safeOptionalText(value: unknown, maximum: number, field: string): string | null {
  if (value === undefined || value === null || value === "") return null;
  return safeText(value, maximum, field);
}

function safeIsoDate(value: unknown, field: string): string | null {
  if (value === undefined || value === null || value === "") return null;
  const normalized = safeText(value, 80, field);
  if (!Number.isFinite(Date.parse(normalized))) throw new Error(`science-${field}-invalid`);
  return new Date(normalized).toISOString();
}

function safeCanonicalSourceUri(value: unknown): string {
  const raw = safeText(value, 2_048, "source-canonical-uri");
  if (/^agentlas-dataset:sha256:[a-f0-9]{64}$/.test(raw)) return raw;
  const identifier = /^(doi|pmid|pmc|arxiv|pdb|uniprot|ncbi):([^\s]+)$/i.exec(raw);
  if (identifier) return `${identifier[1].toLowerCase()}:${identifier[2]}`;
  let parsed: URL;
  try { parsed = new URL(raw); } catch { throw new Error("science-source-canonical-uri-invalid"); }
  if (parsed.protocol !== "https:" || parsed.username || parsed.password) throw new Error("science-source-canonical-uri-invalid");
  const hostname = parsed.hostname.toLowerCase();
  if (hostname === "localhost" || hostname.endsWith(".localhost") || hostname === "0.0.0.0" || hostname === "::1" || /^127\./.test(hostname) || /^10\./.test(hostname) || /^192\.168\./.test(hostname) || /^169\.254\./.test(hostname) || /^172\.(1[6-9]|2\d|3[01])\./.test(hostname)) throw new Error("science-source-canonical-uri-private");
  parsed.hash = "";
  return parsed.toString();
}

function normalizeSemantic(value: unknown): ScienceArtifactSemanticSnapshot {
  const record = safeJsonRecord(value, 512 * 1024, "artifact-semantic");
  const entities = Array.isArray(record.entities) ? record.entities : null;
  const observations = Array.isArray(record.observations) ? record.observations : null;
  if (!entities || entities.length > 2_000 || !observations || observations.length > 5_000) throw new Error("science-artifact-semantic-invalid");
  return {
    title: safeText(record.title, 240, "artifact-semantic-title"),
    summary: safeText(record.summary, 20_000, "artifact-semantic-summary"),
    entities: entities.map((item) => {
      if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error("science-artifact-semantic-entity-invalid");
      const entity = item as Record<string, unknown>;
      return { id: safeText(entity.id, 240, "artifact-entity-id"), label: safeText(entity.label, 500, "artifact-entity-label"), type: safeText(entity.type, 120, "artifact-entity-type") };
    }),
    observations: observations.map((item) => {
      if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error("science-artifact-semantic-observation-invalid");
      const observation = item as Record<string, unknown>;
      const rawValue = observation.value;
      if ((typeof rawValue !== "string" && typeof rawValue !== "number") || (typeof rawValue === "number" && !Number.isFinite(rawValue))) throw new Error("science-artifact-observation-value-invalid");
      const unit = observation.unit === null ? null : safeText(observation.unit, 80, "artifact-observation-unit");
      return { label: safeText(observation.label, 500, "artifact-observation-label"), value: rawValue, unit };
    }),
    warnings: safeTextList(record.warnings, 200, 2_000, "artifact-warning", 0),
  };
}

function normalizeProvenance(value: unknown): ScienceArtifactProvenance {
  const record = safeJsonRecord(value, 512 * 1024, "artifact-provenance");
  return {
    sourceRunId: record.sourceRunId === null ? null : safeText(record.sourceRunId, 240, "artifact-source-run-id"),
    sourceRefs: safeTextList(record.sourceRefs, 2_000, 2_000, "artifact-source-ref", 0),
    datasetSha256: safeTextList(record.datasetSha256, 2_000, 64, "artifact-dataset-sha256", 0).map((item) => safeSha256(item, "artifact-dataset-sha256")),
    codeSha256: record.codeSha256 === null ? null : safeSha256(record.codeSha256, "artifact-code-sha256"),
    environmentSha256: record.environmentSha256 === null ? null : safeSha256(record.environmentSha256, "artifact-environment-sha256"),
  };
}

function defaultLabId(rendererId: ScienceRendererId): string {
  if (rendererId === "agentlas.ketcher") return "chemistry";
  if (rendererId === "agentlas.molstar") return "molecular-structure";
  if (rendererId === "agentlas.vega") return "data-visualization";
  if (rendererId === SCIENCE_NUMERIC_SURFACE_RENDERER_ID) return "data-visualization";
  if (rendererId === "agentlas.cytoscape") return "literature-network";
  if (rendererId === "agentlas.table") return "data-table";
  return "imaging";
}

function normalizeArtifactOrigin(value: unknown): ScienceArtifactOrigin {
  const record = safeJsonRecord(value, 8 * 1024, "artifact-origin");
  if (!SCIENCE_ARTIFACT_ORIGIN_SURFACES.includes(record.surface as ScienceArtifactOrigin["surface"])) throw new Error("science-artifact-origin-surface-invalid");
  const optionalUuid = (key: string) => {
    const candidate = record[key];
    if (candidate === undefined || candidate === null || candidate === "") return null;
    const normalized = String(candidate);
    if (!UUID_RE.test(normalized)) throw new Error(`science-artifact-origin-${key}-invalid`);
    return normalized;
  };
  const origin: ScienceArtifactOrigin = {
    surface: record.surface as ScienceArtifactOrigin["surface"],
    conversationId: optionalUuid("conversationId"),
    messageId: optionalUuid("messageId"),
    loopSessionId: optionalUuid("loopSessionId"),
    runId: optionalUuid("runId"),
    branchId: optionalUuid("branchId"),
  };
  if ((origin.conversationId === null) !== (origin.messageId === null)) throw new Error("science-artifact-origin-message-pair-invalid");
  if (origin.surface === "conversation" && (!origin.conversationId || !origin.messageId)) throw new Error("science-artifact-origin-message-required");
  if (origin.surface === "loop" && (!origin.loopSessionId || !origin.runId)) throw new Error("science-artifact-origin-loop-required");
  if (origin.surface === "legacy" && Object.entries(origin).some(([key, item]) => key !== "surface" && item !== null)) throw new Error("science-artifact-origin-legacy-reference-invalid");
  return origin;
}

function normalizeArtifactLinkageInput(value: unknown, rendererId: ScienceRendererId, fallback?: ScienceArtifactLinkageInput): ScienceArtifactLinkageInput {
  if (value === undefined || value === null) {
    if (fallback) return normalizeArtifactLinkageInput(fallback, rendererId);
    return {
      labId: defaultLabId(rendererId),
      origin: { surface: "legacy", conversationId: null, messageId: null, loopSessionId: null, runId: null, branchId: null },
      parent: null,
      inputs: [],
    };
  }
  const record = safeJsonRecord(value, 64 * 1024, "artifact-linkage");
  const labId = String(record.labId ?? "").toLowerCase();
  if (!LAB_ID_RE.test(labId)) throw new Error("science-artifact-lab-id-invalid");
  const reference = (entry: unknown, field: string) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw new Error(`science-artifact-${field}-invalid`);
    const item = entry as Record<string, unknown>;
    if (!UUID_RE.test(String(item.artifactId ?? ""))) throw new Error(`science-artifact-${field}-id-invalid`);
    return { artifactId: String(item.artifactId), version: safePositiveInteger(item.version, 1, Number.MAX_SAFE_INTEGER, `${field}-version`) };
  };
  const inputsRaw = Array.isArray(record.inputs) ? record.inputs : null;
  if (!inputsRaw || inputsRaw.length > 100) throw new Error("science-artifact-inputs-invalid");
  const inputs = inputsRaw.map((item) => reference(item, "input"));
  if (new Set(inputs.map((item) => `${item.artifactId}:${item.version}`)).size !== inputs.length) throw new Error("science-artifact-input-duplicate");
  return {
    labId,
    origin: normalizeArtifactOrigin(record.origin),
    parent: record.parent === null ? null : reference(record.parent, "parent"),
    inputs,
  };
}

function normalizeRendererBinding(value: unknown): ScienceRendererBinding | null {
  if (value === undefined || value === null) return null;
  const copy = safeJsonRecord(value, 64 * 1024, "renderer-binding");
  if (!isScienceRendererBinding(copy)) throw new Error("science-renderer-binding-invalid");
  return copy;
}

function normalizeExecutorBinding(value: unknown): ScienceRendererExecutorBinding | null {
  if (value === undefined || value === null) return null;
  const copy = safeJsonRecord(value, 64 * 1024, "executor-binding");
  if (!isScienceRendererExecutorBinding(copy)) throw new Error("science-renderer-executor-binding-invalid");
  return copy;
}

function normalizeToolMaterializationPlanInput(
  value: unknown,
  outputOrdinal: number,
  executionLabId: string,
  allowLegacyExecutorlessChemistry = false,
): ScienceToolMaterializationPlanInput {
  const record = safeJsonRecord(value, 96 * 1024, "tool-materialization-plan");
  if (!hasExactKeys(record, ["authorityMode", "artifactKind", "rendererId", "rendererVersion", "rendererBinding", "executorBinding", "outputOrdinal", "outputRole", "outputMimeType", "labId"])) {
    throw new Error("science-tool-materialization-plan-shape-invalid");
  }
  const planOutputOrdinal = safePositiveInteger(record.outputOrdinal, 1, 1_000, "tool-materialization-plan-output-ordinal");
  if (planOutputOrdinal !== outputOrdinal) throw new Error("science-tool-materialization-plan-output-mismatch");
  const authorityMode = String(record.authorityMode ?? "");
  const artifactKind = String(record.artifactKind ?? "") as ScienceArtifactKind;
  const rendererId = String(record.rendererId ?? "") as ScienceRendererId;
  const rendererVersion = safeText(record.rendererVersion, 120, "tool-materialization-plan-renderer-version");
  const outputRole = safeText(record.outputRole, 160, "tool-materialization-plan-output-role");
  const outputMimeType = safeText(record.outputMimeType, 240, "tool-materialization-plan-output-mime");
  const labId = String(record.labId ?? "").toLowerCase();
  if (!LAB_ID_RE.test(labId) || labId !== executionLabId) throw new Error("science-tool-materialization-plan-lab-mismatch");
  const rendererBinding = normalizeRendererBinding(record.rendererBinding);
  const executorBinding = normalizeExecutorBinding(record.executorBinding);
  if (authorityMode === "core") {
    const validVega = artifactKind === "chart.vega" && rendererId === TABLE_TO_VEGA_RENDERER_ID
      && rendererVersion === TABLE_TO_VEGA_RENDERER_VERSION && outputRole === TABLE_TO_VEGA_OUTPUT_ROLE
      && outputMimeType === TABLE_TO_VEGA_OUTPUT_MIME && labId === "data-visualization";
    const validCitationNetwork = artifactKind === "literature.citation-network" && rendererId === CITATION_NETWORK_RENDERER_ID
      && rendererVersion === CITATION_NETWORK_RENDERER_VERSION && outputRole === CITATION_NETWORK_OUTPUT_ROLE
      && outputMimeType === CITATION_NETWORK_OUTPUT_MIME && labId === "literature-network";
    const validAstronomySky = artifactKind === "astronomy.sky-catalog" && rendererId === ASTRONOMY_SKY_RENDERER_ID
      && rendererVersion === ASTRONOMY_SKY_RENDERER_VERSION && outputRole === ASTRONOMY_SKY_OUTPUT_ROLE
      && outputMimeType === ASTRONOMY_SKY_OUTPUT_MIME && labId === "astronomy-sky";
    const validAstronomyLightCurve = artifactKind === "chart.vega" && rendererId === SCIENCE_ASTRONOMY_LIGHT_CURVE_RENDERER_ID
      && rendererVersion === SCIENCE_ASTRONOMY_LIGHT_CURVE_RENDERER_VERSION && outputRole === SCIENCE_ASTRONOMY_LIGHT_CURVE_OUTPUT_ROLE
      && outputMimeType === SCIENCE_ASTRONOMY_LIGHT_CURVE_OUTPUT_MIME && labId === SCIENCE_ASTRONOMY_LIGHT_CURVE_LAB_ID;
    const validBiodiversityMap = artifactKind === "chart.vega" && rendererId === BIODIVERSITY_MAP_RENDERER_ID
      && rendererVersion === BIODIVERSITY_MAP_RENDERER_VERSION && outputRole === BIODIVERSITY_MAP_OUTPUT_ROLE
      && outputMimeType === BIODIVERSITY_MAP_OUTPUT_MIME && labId === "biodiversity-map";
    const validEarthquakeMap = artifactKind === "chart.vega" && rendererId === EARTHQUAKE_MAP_RENDERER_ID
      && rendererVersion === EARTHQUAKE_MAP_RENDERER_VERSION && outputRole === EARTHQUAKE_MAP_OUTPUT_ROLE
      && outputMimeType === EARTHQUAKE_MAP_OUTPUT_MIME && labId === "earthquake-observations";
    const validStatistics = artifactKind === SCIENCE_TABLE_ARTIFACT_KIND && rendererId === SCIENCE_TABLE_RENDERER_ID
      && rendererVersion === SCIENCE_TABLE_RENDERER_VERSION && outputRole === STATISTICS_OUTPUT_ROLE
      && outputMimeType === STATISTICS_OUTPUT_MIME && labId === SCIENCE_STATISTICS_LAB_ID;
    const validPhysics = artifactKind === SCIENCE_TABLE_ARTIFACT_KIND && rendererId === SCIENCE_TABLE_RENDERER_ID
      && rendererVersion === SCIENCE_TABLE_RENDERER_VERSION && outputRole === PHYSICS_OUTPUT_ROLE
      && outputMimeType === PHYSICS_OUTPUT_MIME && labId === SCIENCE_PHYSICS_LAB_ID;
    if ((!validVega && !validCitationNetwork && !validAstronomySky && !validAstronomyLightCurve && !validBiodiversityMap && !validEarthquakeMap && !validStatistics && !validPhysics) || rendererBinding !== null || executorBinding !== null) {
      throw new Error("science-tool-materialization-plan-core-invalid");
    }
  } else if (authorityMode === "signed-pack") {
    if (!((artifactKind === "chemistry.document" && rendererId === "agentlas.ketcher")
      || (artifactKind === "protein.structure" && rendererId === "agentlas.molstar"))
      || !rendererBinding || rendererBinding.rendererId !== rendererId || rendererBinding.rendererVersion !== rendererVersion) {
      throw new Error("science-tool-materialization-plan-binding-invalid");
    }
    if (artifactKind === "chemistry.document") {
      if ((!executorBinding && !allowLegacyExecutorlessChemistry)
        || (executorBinding && (![SMILES_TO_KETCHER_TOOL_ID, SOURCE_TO_KETCHER_TOOL_ID].includes(executorBinding.executorId)
          || !scienceRendererExecutorMatchesRenderer(executorBinding, rendererBinding)))) {
        throw new Error("science-tool-materialization-plan-executor-binding-invalid");
      }
    } else if (executorBinding !== null) {
      throw new Error("science-tool-materialization-plan-executor-binding-invalid");
    }
  } else {
    throw new Error("science-tool-materialization-plan-authority-invalid");
  }
  return {
    authorityMode: authorityMode as ScienceToolMaterializationPlanInput["authorityMode"],
    artifactKind,
    rendererId,
    rendererVersion,
    rendererBinding,
    executorBinding,
    outputOrdinal: planOutputOrdinal,
    outputRole,
    outputMimeType,
    labId,
  };
}

function normalizeChemistryPayload(value: unknown): ScienceChemistryDocumentPayload {
  const payload = safeJsonRecord(value, 4 * 1024 * 1024, "chemistry-document-payload");
  if (!isScienceChemistryDocumentPayload(payload)) throw new Error("science-chemistry-document-payload-invalid");
  const document = payload.document;
  if (sha256Text(document.ket) !== document.ketSha256) throw new Error("science-chemistry-ket-integrity-failed");
  if (sha256Text(document.canonicalSmiles) !== document.canonicalSmilesSha256) throw new Error("science-chemistry-smiles-integrity-failed");
  let ket: Record<string, unknown>;
  try {
    ket = JSON.parse(document.ket) as Record<string, unknown>;
  } catch {
    throw new Error("science-chemistry-ket-json-invalid");
  }
  const root = ket.root && typeof ket.root === "object" && !Array.isArray(ket.root) ? ket.root as Record<string, unknown> : null;
  const nodes = root && Array.isArray(root.nodes) ? root.nodes : null;
  if (!nodes || nodes.length < 1 || nodes.length > 50_000) throw new Error("science-chemistry-ket-structure-invalid");
  let atomCount = 0;
  let bondCount = 0;
  const seen = new Set<string>();
  for (const node of nodes) {
    const record = node && typeof node === "object" && !Array.isArray(node) ? node as Record<string, unknown> : null;
    const ref = record && typeof record.$ref === "string" ? record.$ref : "";
    if (!ref || seen.has(ref)) throw new Error("science-chemistry-ket-reference-invalid");
    seen.add(ref);
    const molecule = ket[ref] && typeof ket[ref] === "object" && !Array.isArray(ket[ref]) ? ket[ref] as Record<string, unknown> : null;
    if (!molecule || molecule.type !== "molecule" || !Array.isArray(molecule.atoms) || !Array.isArray(molecule.bonds)) {
      throw new Error("science-chemistry-ket-molecule-invalid");
    }
    atomCount += molecule.atoms.length;
    bondCount += molecule.bonds.length;
  }
  if (atomCount < 1 || atomCount > 50_000 || bondCount > 100_000
    || atomCount !== payload.validation.atomCount || bondCount !== payload.validation.bondCount) {
    throw new Error("science-chemistry-ket-counts-invalid");
  }
  return payload;
}

function validateCitationNetworkPayload(value: unknown, run: ScienceResearchRun): void {
  const payload = safeJsonRecord(value, 8 * 1024 * 1024, "citation-network-payload");
  if (!hasExactKeys(payload, ["network", "view", "provenance"])) throw new Error("science-citation-network-payload-invalid");
  const network = safeJsonRecord(payload.network, 7 * 1024 * 1024, "citation-network");
  const view = safeJsonRecord(payload.view, 64 * 1024, "citation-network-view");
  const provenance = safeJsonRecord(payload.provenance, 64 * 1024, "citation-network-provenance");
  if (!hasExactKeys(network, ["nodes", "edges"]) || !hasExactKeys(view, ["layout", "relations"]) || !hasExactKeys(provenance, ["academicSearchRunId", "academicSearchOutputSha256", "query"])) {
    throw new Error("science-citation-network-payload-invalid");
  }
  if (!Array.isArray(network.nodes) || network.nodes.length < 1 || network.nodes.length > 200 || !Array.isArray(network.edges) || network.edges.length > 40_000) {
    throw new Error("science-citation-network-payload-invalid");
  }
  const ids = new Set<string>();
  for (const raw of network.nodes) {
    const node = safeJsonRecord(raw, 64 * 1024, "citation-network-node");
    if (!hasExactKeys(node, ["id", "canonicalId", "sourceId", "sourceVersionId", "openAlexId", "title", "authors", "publicationYear", "containerTitle", "citationCount", "landingUrl", "isSeed"])) throw new Error("science-citation-network-node-invalid");
    const id = safeText(node.id, 500, "citation-network-node-id");
    if (ids.has(id)) throw new Error("science-citation-network-node-duplicate");
    ids.add(id);
    safeText(node.title, 1_000, "citation-network-node-title");
    safeText(node.landingUrl, 4_000, "citation-network-node-url");
    if (!Array.isArray(node.authors) || node.authors.length > 50 || node.authors.some((author) => typeof author !== "string" || author.length > 500)) throw new Error("science-citation-network-node-authors-invalid");
    if (node.openAlexId !== null && (typeof node.openAlexId !== "string" || !/^https:\/\/openalex\.org\/W\d+$/.test(node.openAlexId))) throw new Error("science-citation-network-node-openalex-invalid");
  }
  const edgeIds = new Set<string>();
  for (const raw of network.edges) {
    const edge = safeJsonRecord(raw, 8 * 1024, "citation-network-edge");
    if (!hasExactKeys(edge, ["id", "source", "target", "relation"]) || !ids.has(String(edge.source)) || !ids.has(String(edge.target)) || edge.source === edge.target || !["cites", "related"].includes(String(edge.relation))) throw new Error("science-citation-network-edge-invalid");
    const edgeId = safeText(edge.id, 1_600, "citation-network-edge-id");
    if (edgeIds.has(edgeId)) throw new Error("science-citation-network-edge-duplicate");
    edgeIds.add(edgeId);
  }
  if (view.layout !== "cose" || !Array.isArray(view.relations) || JSON.stringify(view.relations) !== JSON.stringify(["cites", "related"])) throw new Error("science-citation-network-view-invalid");
  if (provenance.academicSearchRunId !== run.parentRunId || !SHA256_RE.test(String(provenance.academicSearchOutputSha256 ?? "")) || typeof provenance.query !== "string" || !provenance.query.trim()) {
    throw new Error("science-citation-network-provenance-invalid");
  }
}

function validateAstronomySkyPayload(value: unknown, run?: ScienceResearchRun): {
  sourceId: string;
  sourceVersionId: string;
  catalogOutputSha256: string;
  rawResponseSha256: string;
  objectsSha256: string;
} {
  const payload = safeJsonRecord(value, 8 * 1024 * 1024, "astronomy-sky-payload");
  if (!hasExactKeys(payload, ["catalog", "view", "provenance"])) throw new Error("science-astronomy-sky-payload-invalid");
  const catalog = safeJsonRecord(payload.catalog, 7 * 1024 * 1024, "astronomy-sky-catalog");
  const view = safeJsonRecord(payload.view, 16 * 1024, "astronomy-sky-view");
  const provenance = safeJsonRecord(payload.provenance, 64 * 1024, "astronomy-sky-provenance");
  if (!hasExactKeys(catalog, ["provider", "sourceId", "sourceVersionId", "center", "radiusDeg", "objects", "objectTypeCounts"])
    || catalog.provider !== "simbad-tap" || !UUID_RE.test(String(catalog.sourceId ?? ""))
    || !UUID_RE.test(String(catalog.sourceVersionId ?? ""))) {
    throw new Error("science-astronomy-sky-catalog-invalid");
  }
  const center = safeJsonRecord(catalog.center, 1_024, "astronomy-sky-center");
  if (!hasExactKeys(center, ["raDeg", "decDeg"])) throw new Error("science-astronomy-sky-center-invalid");
  const finite = (candidate: unknown, minimum: number, maximum: number, code: string): number => {
    if (typeof candidate !== "number" || !Number.isFinite(candidate) || candidate < minimum || candidate > maximum) throw new Error(code);
    return candidate;
  };
  finite(center.raDeg, 0, 359.99999999, "science-astronomy-sky-center-invalid");
  finite(center.decDeg, -90, 90, "science-astronomy-sky-center-invalid");
  finite(catalog.radiusDeg, 0.001, 10, "science-astronomy-sky-radius-invalid");
  if (!Array.isArray(catalog.objects) || catalog.objects.length > 500) throw new Error("science-astronomy-sky-objects-invalid");
  const objectIds = new Set<string>();
  const typeCounts = new Map<string, number>();
  const nullableFinite = (candidate: unknown): boolean => candidate === null || (typeof candidate === "number" && Number.isFinite(candidate));
  for (const item of catalog.objects) {
    const object = safeJsonRecord(item, 8 * 1024, "astronomy-sky-object");
    if (!hasExactKeys(object, ["id", "mainId", "raDeg", "decDeg", "objectType", "spectralType", "parallaxMas", "properMotionRaMasYr", "properMotionDecMasYr", "radialVelocityKmS", "redshift"])) {
      throw new Error("science-astronomy-sky-object-invalid");
    }
    const id = String(object.id ?? "");
    const objectType = safeText(object.objectType, 80, "astronomy-sky-object-type");
    safeText(object.mainId, 500, "astronomy-sky-main-id");
    if (!UUID_RE.test(id) || objectIds.has(id)) throw new Error("science-astronomy-sky-object-invalid");
    objectIds.add(id);
    finite(object.raDeg, 0, 359.99999999, "science-astronomy-sky-object-invalid");
    finite(object.decDeg, -90, 90, "science-astronomy-sky-object-invalid");
    if (object.spectralType !== null) safeText(object.spectralType, 160, "astronomy-sky-spectral-type");
    for (const key of ["parallaxMas", "properMotionRaMasYr", "properMotionDecMasYr", "radialVelocityKmS", "redshift"]) {
      if (!nullableFinite(object[key])) throw new Error("science-astronomy-sky-measurement-invalid");
    }
    typeCounts.set(objectType, (typeCounts.get(objectType) ?? 0) + 1);
  }
  const expectedCounts = [...typeCounts.entries()].sort((left, right) => right[1] - left[1]
    || (left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0)).slice(0, 12)
    .map(([type, count]) => ({ type, count }));
  if (sha256Json(catalog.objectTypeCounts) !== sha256Json(expectedCounts)) throw new Error("science-astronomy-sky-type-counts-invalid");
  if (!hasExactKeys(view, ["projection", "invertRightAscension", "selectedObjectId"])
    || view.projection !== "local-tangent" || view.invertRightAscension !== true
    || (view.selectedObjectId !== null && (!UUID_RE.test(String(view.selectedObjectId)) || !objectIds.has(String(view.selectedObjectId))))) {
    throw new Error("science-astronomy-sky-view-invalid");
  }
  if (!hasExactKeys(provenance, ["astronomyCatalogRunId", "astronomyCatalogOutputSha256", "rawResponseSha256", "requestSha256", "responseSha256", "normalizedSha256", "endpoint", "retrievedAt", "adql", "sourceAuthority", "rendererReceipt"])
    || !UUID_RE.test(String(provenance.astronomyCatalogRunId ?? ""))
    || (run !== undefined && provenance.astronomyCatalogRunId !== run.parentRunId)
    || !SHA256_RE.test(String(provenance.astronomyCatalogOutputSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.rawResponseSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.requestSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.responseSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.normalizedSha256 ?? ""))
    || provenance.rawResponseSha256 !== provenance.responseSha256
    || provenance.endpoint !== "https://simbad.cds.unistra.fr/simbad/sim-tap/sync"
    || !safeText(provenance.retrievedAt, 80, "astronomy-sky-retrieved-at")
    || !safeText(provenance.adql, 20_000, "astronomy-sky-adql")
    || !isScienceAstronomySourceAuthority(provenance.sourceAuthority)
    || !isScienceAstronomyRendererReceipt(provenance.rendererReceipt, { catalog, view })) {
    throw new Error("science-astronomy-sky-provenance-invalid");
  }
  return {
    sourceId: String(catalog.sourceId),
    sourceVersionId: String(catalog.sourceVersionId),
    catalogOutputSha256: String(provenance.astronomyCatalogOutputSha256),
    rawResponseSha256: String(provenance.rawResponseSha256),
    objectsSha256: sha256Json(catalog.objects),
  };
}

function validateBiodiversityMapPayload(value: unknown, run: ScienceResearchRun): {
  sourceId: string;
  sourceVersionId: string;
  catalogOutputSha256: string;
  rawResponseSha256: string;
  occurrencesSha256: string;
} {
  const payload = safeJsonRecord(value, 8 * 1024 * 1024, "biodiversity-map-payload");
  if (!hasExactKeys(payload, ["spec", "catalog", "provenance"])) throw new Error("science-biodiversity-map-payload-invalid");
  validateVegaSpec(payload);
  const catalog = safeJsonRecord(payload.catalog, 7 * 1024 * 1024, "biodiversity-map-catalog");
  const provenance = safeJsonRecord(payload.provenance, 64 * 1024, "biodiversity-map-provenance");
  if (!hasExactKeys(catalog, ["provider", "sourceId", "sourceVersionId", "query", "occurrences", "basisOfRecordCounts"])
    || catalog.provider !== "gbif-occurrence" || !UUID_RE.test(String(catalog.sourceId ?? ""))
    || !UUID_RE.test(String(catalog.sourceVersionId ?? "")) || !Array.isArray(catalog.occurrences)
    || catalog.occurrences.length > 300 || !Array.isArray(catalog.basisOfRecordCounts)) {
    throw new Error("science-biodiversity-map-catalog-invalid");
  }
  const query = safeJsonRecord(catalog.query, 8 * 1024, "biodiversity-map-query");
  if (!hasExactKeys(query, ["scientificName", "countryCode", "fromYear", "toYear", "limit", "hasCoordinate", "occurrenceStatus"])
    || !safeText(query.scientificName, 500, "biodiversity-map-scientific-name")
    || query.hasCoordinate !== true || query.occurrenceStatus !== "PRESENT"
    || !Number.isSafeInteger(query.limit) || Number(query.limit) < 1 || Number(query.limit) > 300) {
    throw new Error("science-biodiversity-map-query-invalid");
  }
  const ids = new Set<string>();
  const basis = new Map<string, number>();
  for (const item of catalog.occurrences) {
    const occurrence = safeJsonRecord(item, 16 * 1024, "biodiversity-map-occurrence");
    if (!hasExactKeys(occurrence, ["id", "gbifKey", "scientificName", "species", "genus", "family", "order", "className", "phylum", "kingdom", "latitude", "longitude", "eventDate", "year", "basisOfRecord", "countryCode", "datasetKey", "issues"])) {
      throw new Error("science-biodiversity-map-occurrence-invalid");
    }
    const id = String(occurrence.id ?? "");
    const recordBasis = safeText(occurrence.basisOfRecord, 120, "biodiversity-map-basis");
    if (!UUID_RE.test(id) || ids.has(id) || !/^\d{1,30}$/.test(String(occurrence.gbifKey ?? ""))
      || !safeText(occurrence.scientificName, 500, "biodiversity-map-name")
      || typeof occurrence.latitude !== "number" || !Number.isFinite(occurrence.latitude) || occurrence.latitude < -90 || occurrence.latitude > 90
      || typeof occurrence.longitude !== "number" || !Number.isFinite(occurrence.longitude) || occurrence.longitude < -180 || occurrence.longitude > 180
      || !Array.isArray(occurrence.issues) || occurrence.issues.length > 100) {
      throw new Error("science-biodiversity-map-occurrence-invalid");
    }
    ids.add(id);
    basis.set(recordBasis, (basis.get(recordBasis) ?? 0) + 1);
  }
  const expectedBasis = [...basis.entries()].sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([basisOfRecord, count]) => ({ basisOfRecord, count }));
  if (sha256Json(catalog.basisOfRecordCounts) !== sha256Json(expectedBasis)) throw new Error("science-biodiversity-map-basis-counts-invalid");
  if (!hasExactKeys(provenance, ["biodiversityCatalogRunId", "biodiversityCatalogOutputSha256", "rawResponseSha256", "requestSha256", "responseSha256", "endpoint", "retrievedAt"])
    || provenance.biodiversityCatalogRunId !== run.parentRunId
    || !SHA256_RE.test(String(provenance.biodiversityCatalogOutputSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.rawResponseSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.requestSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.responseSha256 ?? ""))
    || provenance.rawResponseSha256 !== provenance.responseSha256
    || provenance.endpoint !== "https://api.gbif.org/v1/occurrence/search"
    || !safeText(provenance.retrievedAt, 80, "biodiversity-map-retrieved-at")) {
    throw new Error("science-biodiversity-map-provenance-invalid");
  }
  return {
    sourceId: String(catalog.sourceId),
    sourceVersionId: String(catalog.sourceVersionId),
    catalogOutputSha256: String(provenance.biodiversityCatalogOutputSha256),
    rawResponseSha256: String(provenance.rawResponseSha256),
    occurrencesSha256: sha256Json(catalog.occurrences),
  };
}

function validateEarthquakeMapPayload(value: unknown, run: ScienceResearchRun): {
  sourceId: string; sourceVersionId: string; catalogOutputSha256: string; rawResponseSha256: string; normalizedSha256: string; eventsSha256: string;
} {
  const payload = safeJsonRecord(value, 8 * 1024 * 1024, "earthquake-map-payload");
  if (!hasExactKeys(payload, ["spec", "catalog", "provenance"])) throw new Error("science-earthquake-map-payload-invalid");
  validateVegaSpec(payload);
  const catalog = safeJsonRecord(payload.catalog, 7 * 1024 * 1024, "earthquake-map-catalog");
  const provenance = safeJsonRecord(payload.provenance, 64 * 1024, "earthquake-map-provenance");
  if (!hasExactKeys(catalog, ["provider", "sourceId", "sourceVersionId", "query", "normalizedSha256", "events"])
    || catalog.provider !== "usgs-fdsn-event" || !UUID_RE.test(String(catalog.sourceId ?? "")) || !UUID_RE.test(String(catalog.sourceVersionId ?? ""))
    || !SHA256_RE.test(String(catalog.normalizedSha256 ?? "")) || !Array.isArray(catalog.events) || catalog.events.length > 2_000) {
    throw new Error("science-earthquake-map-catalog-invalid");
  }
  const ids = new Set<string>();
  for (const item of catalog.events) {
    const event = safeJsonRecord(item, 24 * 1024, "earthquake-map-event");
    if (!hasExactKeys(event, ["id", "time", "updatedAt", "magnitude", "magnitudeType", "place", "longitude", "latitude", "depthKm", "feltReports", "significance", "tsunami", "alert", "status", "eventType", "detailUrl", "publicUrl"])) {
      throw new Error("science-earthquake-map-event-invalid");
    }
    const id = safeText(event.id, 120, "earthquake-map-event-id");
    const magnitudeValid = event.magnitude === null || (typeof event.magnitude === "number" && Number.isFinite(event.magnitude) && event.magnitude >= -2 && event.magnitude <= 10);
    if (ids.has(id) || !safeText(event.time, 80, "earthquake-map-event-time") || !safeText(event.updatedAt, 80, "earthquake-map-event-updated")
      || !magnitudeValid || typeof event.longitude !== "number" || !Number.isFinite(event.longitude) || event.longitude < -180 || event.longitude > 180
      || typeof event.latitude !== "number" || !Number.isFinite(event.latitude) || event.latitude < -90 || event.latitude > 90
      || typeof event.depthKm !== "number" || !Number.isFinite(event.depthKm) || event.depthKm < -10 || event.depthKm > 1_000
      || typeof event.tsunami !== "boolean" || !safeText(event.status, 80, "earthquake-map-event-status")
      || !safeText(event.eventType, 80, "earthquake-map-event-type") || !safeText(event.detailUrl, 2_000, "earthquake-map-event-detail")
      || !safeText(event.publicUrl, 2_000, "earthquake-map-event-public")) throw new Error("science-earthquake-map-event-invalid");
    ids.add(id);
  }
  if (!hasExactKeys(provenance, ["earthquakeCatalogRunId", "earthquakeCatalogOutputSha256", "rawResponseSha256", "requestSha256", "normalizedSha256", "endpoint", "retrievedAt"])
    || provenance.earthquakeCatalogRunId !== run.parentRunId || !SHA256_RE.test(String(provenance.earthquakeCatalogOutputSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.rawResponseSha256 ?? "")) || !SHA256_RE.test(String(provenance.requestSha256 ?? ""))
    || !SHA256_RE.test(String(provenance.normalizedSha256 ?? "")) || provenance.normalizedSha256 !== catalog.normalizedSha256
    || provenance.endpoint !== "https://earthquake.usgs.gov/fdsnws/event/1/query" || !safeText(provenance.retrievedAt, 80, "earthquake-map-retrieved-at")) {
    throw new Error("science-earthquake-map-provenance-invalid");
  }
  return {
    sourceId: String(catalog.sourceId), sourceVersionId: String(catalog.sourceVersionId),
    catalogOutputSha256: String(provenance.earthquakeCatalogOutputSha256), rawResponseSha256: String(provenance.rawResponseSha256),
    normalizedSha256: String(provenance.normalizedSha256), eventsSha256: sha256Json(catalog.events),
  };
}

function validateGenomicsVariantTrackPayload(value: unknown, run?: ScienceResearchRun): {
  assemblySourceId: string;
  assemblySourceVersionId: string;
  variantSourceId: string;
  variantSourceVersionId: string;
  assemblyResponseSha256: string;
  variantResponseSha256: string;
} {
  const payload = safeJsonRecord(value, 4 * 1024 * 1024, "genomics-variant-track-payload");
  if (!hasExactKeys(payload, ["schema", "assembly", "region", "variants", "provenance"])
    || payload.schema !== "agentlas.science-genomics-variant-track/v1") {
    throw new Error("science-genomics-variant-track-payload-invalid");
  }
  const assembly = safeJsonRecord(payload.assembly, 16 * 1024, "genomics-assembly");
  const region = safeJsonRecord(payload.region, 4 * 1024, "genomics-region");
  const provenance = safeJsonRecord(payload.provenance, 64 * 1024, "genomics-provenance");
  if (!hasExactKeys(assembly, ["species", "name", "defaultCoordSystemVersion", "refNameLength", "aliases"])
    || !safeText(assembly.species, 80, "genomics-species") || !/^[a-z][a-z0-9_]+$/.test(String(assembly.species))
    || !safeText(assembly.name, 120, "genomics-assembly-name")
    || !safeText(assembly.defaultCoordSystemVersion, 120, "genomics-coordinate-version")
    || !Number.isSafeInteger(assembly.refNameLength) || Number(assembly.refNameLength) < 1 || Number(assembly.refNameLength) > 500_000_000
    || !Array.isArray(assembly.aliases) || assembly.aliases.length > 24) {
    throw new Error("science-genomics-assembly-invalid");
  }
  if (!hasExactKeys(region, ["refName", "start", "end"])
    || !safeText(region.refName, 120, "genomics-reference")
    || !Number.isSafeInteger(region.start) || Number(region.start) < 1
    || !Number.isSafeInteger(region.end) || Number(region.end) < Number(region.start)
    || Number(region.end) > Number(assembly.refNameLength)
    || Number(region.end) - Number(region.start) + 1 > 1_000_000) {
    throw new Error("science-genomics-region-invalid");
  }
  if (!Array.isArray(payload.variants) || payload.variants.length > 8_000) throw new Error("science-genomics-variants-invalid");
  const ids = new Set<string>();
  for (const [index, item] of payload.variants.entries()) {
    const variant = safeJsonRecord(item, 16 * 1024, `genomics-variant-${index}`);
    if (!hasExactKeys(variant, ["id", "name", "refName", "start", "end", "start0", "end0", "strand", "source", "alleles", "consequenceTypes", "clinicalSignificance"])
      || !UUID_RE.test(String(variant.id ?? "")) || ids.has(String(variant.id))
      || !safeText(variant.name, 240, "genomics-variant-name") || variant.refName !== region.refName
      || !Number.isSafeInteger(variant.start) || Number(variant.start) < Number(region.start)
      || !Number.isSafeInteger(variant.end) || Number(variant.end) < Number(variant.start) || Number(variant.end) > Number(region.end)
      || variant.start0 !== Number(variant.start) - 1 || variant.end0 !== variant.end
      || ![-1, 0, 1].includes(Number(variant.strand))
      || !safeText(variant.source, 120, "genomics-variant-source")
      || !Array.isArray(variant.alleles) || variant.alleles.length > 24
      || !Array.isArray(variant.consequenceTypes) || variant.consequenceTypes.length > 24
      || !Array.isArray(variant.clinicalSignificance) || variant.clinicalSignificance.length > 24) {
      throw new Error("science-genomics-variant-invalid");
    }
    ids.add(String(variant.id));
  }
  if (!hasExactKeys(provenance, ["runId", "assemblySourceId", "assemblySourceVersionId", "variantSourceId", "variantSourceVersionId", "assemblyEndpoint", "variantEndpoint", "assemblyResponseSha256", "variantResponseSha256", "retrievedAt"])
    || !UUID_RE.test(String(provenance.runId ?? ""))
    || !UUID_RE.test(String(provenance.assemblySourceId ?? "")) || !UUID_RE.test(String(provenance.assemblySourceVersionId ?? ""))
    || !UUID_RE.test(String(provenance.variantSourceId ?? "")) || !UUID_RE.test(String(provenance.variantSourceVersionId ?? ""))
    || !SHA256_RE.test(String(provenance.assemblyResponseSha256 ?? "")) || !SHA256_RE.test(String(provenance.variantResponseSha256 ?? ""))
    || !safeText(provenance.retrievedAt, 80, "genomics-retrieved-at")
    || !String(provenance.assemblyEndpoint ?? "").startsWith("https://rest.ensembl.org/info/assembly/")
    || !String(provenance.variantEndpoint ?? "").startsWith("https://rest.ensembl.org/overlap/region/")) {
    throw new Error("science-genomics-provenance-invalid");
  }
  if (run) {
    const assemblyOutput = run.outputs.find((resource) => resource.role === "assembly-response" && resource.mimeType === "application/json");
    const variantOutput = run.outputs.find((resource) => resource.role === "provider-response" && resource.mimeType === "application/json");
    if (run.toolId !== "agentlas.ensembl-variant-track" || run.toolVersion !== "1.0.0" || run.status !== "succeeded"
      || provenance.runId !== run.id || !assemblyOutput || !variantOutput
      || provenance.assemblyResponseSha256 !== assemblyOutput.sha256
      || provenance.variantResponseSha256 !== variantOutput.sha256) {
      throw new Error("science-genomics-run-closure-invalid");
    }
  }
  return {
    assemblySourceId: String(provenance.assemblySourceId),
    assemblySourceVersionId: String(provenance.assemblySourceVersionId),
    variantSourceId: String(provenance.variantSourceId),
    variantSourceVersionId: String(provenance.variantSourceVersionId),
    assemblyResponseSha256: String(provenance.assemblyResponseSha256),
    variantResponseSha256: String(provenance.variantResponseSha256),
  };
}

function validateVegaSpec(payload: Record<string, unknown>): void {
  const spec = payload.spec;
  if (!spec || typeof spec !== "object" || Array.isArray(spec)) throw new Error("science-vega-spec-invalid");
  const forbidden = new Set(["url", "signal", "signals", "expr", "expression", "on", "href", "test"]);
  let nodes = 0;
  const visit = (entry: unknown, depth: number): void => {
    if (++nodes > 100_000 || depth > 40) throw new Error("science-vega-spec-too-complex");
    if (entry === null || typeof entry === "string" || typeof entry === "boolean") return;
    if (typeof entry === "number") {
      if (!Number.isFinite(entry)) throw new Error("science-vega-spec-invalid");
      return;
    }
    if (Array.isArray(entry)) {
      for (const item of entry) visit(item, depth + 1);
      return;
    }
    if (typeof entry !== "object") throw new Error("science-vega-spec-invalid");
    for (const [key, item] of Object.entries(entry as Record<string, unknown>)) {
      if (forbidden.has(key.toLowerCase()) || ["__proto__", "prototype", "constructor"].includes(key)) throw new Error(`science-vega-spec-forbidden-${key.toLowerCase()}`);
      visit(item, depth + 1);
    }
  };
  visit(spec, 0);
  const data = (spec as Record<string, unknown>).data;
  if (data !== undefined && (!Array.isArray(data) || data.some((item) => {
    if (!item || typeof item !== "object" || Array.isArray(item)) return true;
    if ("values" in item || "source" in item) return false;
    const transforms = (item as Record<string, unknown>).transform;
    return !Array.isArray(transforms) || transforms.length !== 1
      || !transforms[0] || typeof transforms[0] !== "object" || Array.isArray(transforms[0])
      || (transforms[0] as Record<string, unknown>).type !== "graticule";
  }))) throw new Error("science-vega-data-must-be-inline");
}

function pngDimensions(bytes: Buffer): { width: number; height: number } {
  if (bytes.length < 24 || !bytes.subarray(0, 8).equals(PNG_SIGNATURE) || bytes.toString("ascii", 12, 16) !== "IHDR") throw new Error("science-capture-png-invalid");
  const width = bytes.readUInt32BE(16);
  const height = bytes.readUInt32BE(20);
  if (width < 1 || height < 1 || width > 16_384 || height > 16_384 || width * height > 48_000_000) throw new Error("science-capture-png-dimensions-invalid");
  return { width, height };
}

function validatedStatisticsFigureSvgBytes(bytes: Buffer, expectedSha256?: string): string {
  if (!Buffer.isBuffer(bytes) || bytes.length < 128 || bytes.length > 24 * 1024 * 1024) {
    throw new Error("science-statistics-figure-vector-bytes-invalid");
  }
  const svg = bytes.toString("utf8");
  if (!Buffer.from(svg, "utf8").equals(bytes) || !svg.startsWith("<svg ") || !svg.endsWith("</svg>")
    || /<(?:script|foreignObject|iframe|object|embed|image)\b/iu.test(svg)
    || /(?:href|src)\s*=\s*["']\s*(?:https?:|file:|javascript:|data:)/iu.test(svg)) {
    throw new Error("science-statistics-figure-vector-bytes-invalid");
  }
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  if (expectedSha256 !== undefined && sha256 !== expectedSha256) {
    throw new Error("science-statistics-figure-vector-bytes-invalid");
  }
  return svg;
}

function sourceFigureDimensions(bytes: Buffer, mimeType: ScienceSourceFigure["mimeType"]): { width: number; height: number } {
  if (mimeType === "image/png") return pngDimensions(bytes);
  if (mimeType === "image/jpeg") {
    if (bytes.length < 4 || bytes[0] !== 0xff || bytes[1] !== 0xd8) throw new Error("science-source-figure-image-invalid");
    let offset = 2;
    while (offset + 9 < bytes.length) {
      if (bytes[offset] !== 0xff) { offset += 1; continue; }
      const marker = bytes[offset + 1];
      if (marker === 0xd9 || marker === 0xda) break;
      const length = bytes.readUInt16BE(offset + 2);
      if (length < 2 || offset + 2 + length > bytes.length) throw new Error("science-source-figure-image-invalid");
      if ([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker)) {
        const height = bytes.readUInt16BE(offset + 5);
        const width = bytes.readUInt16BE(offset + 7);
        if (width < 1 || height < 1) throw new Error("science-source-figure-image-invalid");
        return { width, height };
      }
      offset += 2 + length;
    }
    throw new Error("science-source-figure-image-invalid");
  }
  if (bytes.length < 30 || bytes.toString("ascii", 0, 4) !== "RIFF" || bytes.toString("ascii", 8, 12) !== "WEBP") throw new Error("science-source-figure-image-invalid");
  const chunk = bytes.toString("ascii", 12, 16);
  if (chunk === "VP8X") return { width: 1 + bytes.readUIntLE(24, 3), height: 1 + bytes.readUIntLE(27, 3) };
  if (chunk === "VP8L") {
    const bits = bytes.readUInt32LE(21);
    return { width: 1 + (bits & 0x3fff), height: 1 + ((bits >> 14) & 0x3fff) };
  }
  if (chunk === "VP8 " && bytes.length >= 30 && bytes[23] === 0x9d && bytes[24] === 0x01 && bytes[25] === 0x2a) {
    return { width: bytes.readUInt16LE(26) & 0x3fff, height: bytes.readUInt16LE(28) & 0x3fff };
  }
  throw new Error("science-source-figure-image-invalid");
}

function normalizeRenderContext(value: unknown): ScienceArtifactVisualCapture["renderContext"] {
  const record = safeJsonRecord(value, 16 * 1024, "capture-render-context");
  const finite = (key: string, minimum: number, maximum: number) => {
    const candidate = record[key];
    if (typeof candidate !== "number" || !Number.isFinite(candidate) || candidate < minimum || candidate > maximum) throw new Error(`science-capture-render-context-${key}-invalid`);
    return candidate;
  };
  if (record.colorScheme !== "light" && record.colorScheme !== "dark") throw new Error("science-capture-render-context-color-scheme-invalid");
  return {
    electronVersion: safeText(record.electronVersion, 80, "capture-electron-version"),
    chromiumVersion: safeText(record.chromiumVersion, 80, "capture-chromium-version"),
    platform: safeText(record.platform, 40, "capture-platform"),
    architecture: safeText(record.architecture, 40, "capture-architecture"),
    locale: safeText(record.locale, 80, "capture-locale"),
    colorScheme: record.colorScheme,
    deviceScaleFactor: finite("deviceScaleFactor", 0.25, 8),
    cssWidth: finite("cssWidth", 1, 4096),
    cssHeight: finite("cssHeight", 1, 4096),
    pixelWidth: finite("pixelWidth", 1, 16_384),
    pixelHeight: finite("pixelHeight", 1, 16_384),
  };
}

function parseTextList(value: unknown): string[] {
  try {
    const parsed = JSON.parse(String(value));
    return Array.isArray(parsed) && parsed.every((item) => typeof item === "string") ? parsed : [];
  } catch {
    return [];
  }
}

function parseObject(value: unknown): Record<string, unknown> {
  try {
    const parsed = JSON.parse(String(value));
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}

function parseArray(value: unknown): unknown[] {
  try {
    const parsed = JSON.parse(String(value));
    if (!Array.isArray(parsed)) throw new Error("science-json-array-invalid");
    return parsed;
  } catch {
    throw new Error("science-json-array-invalid");
  }
}

function defaultTitle(question: string): string {
  const firstLine = question.split("\n", 1)[0].trim();
  return firstLine.length > 72 ? `${firstLine.slice(0, 69).trimEnd()}…` : firstLine;
}

function normalizeRelatedDomains(value: unknown, primaryDomain: ScienceDomain): ScienceDomain[] {
  if (value === undefined) return [];
  if (!Array.isArray(value) || value.length > SCIENCE_DOMAINS.length - 1) throw new Error("science-related-domains-invalid");
  const domains = value.map((item) => safeDomain(item));
  if (domains.includes(primaryDomain) || new Set(domains).size !== domains.length) throw new Error("science-related-domains-invalid");
  return domains;
}

