function researchEpisodeResultFromRow(
  row: Record<string, unknown>,
  runIds: string[],
  artifacts: ScienceResearchEpisodeArtifactBinding[],
  evidenceSpanIds: string[],
): ScienceResearchEpisodeResult {
  const result: ScienceResearchEpisodeResult = {
    episodeId: String(row.episode_id),
    outcome: String(row.outcome) as ScienceResearchEpisodeOutcome,
    observationSummary: String(row.observation_summary),
    conclusion: String(row.conclusion),
    nextAction: String(row.next_action),
    runIds: [...runIds].sort(),
    artifacts: [...artifacts].sort((a, b) => a.artifactId.localeCompare(b.artifactId) || a.artifactVersion - b.artifactVersion),
    evidenceSpanIds: [...evidenceSpanIds].sort(),
    resultSha256: String(row.result_sha256),
    createdAt: String(row.created_at),
  };
  if (!UUID_RE.test(result.episodeId) || !["supported", "contradicted", "inconclusive", "not-tested"].includes(result.outcome)
    || !SHA256_RE.test(result.resultSha256)
    || result.runIds.some((id) => !UUID_RE.test(id))
    || result.artifacts.some((item) => !UUID_RE.test(item.artifactId) || !Number.isSafeInteger(item.artifactVersion)
      || item.artifactVersion < 1 || !SHA256_RE.test(item.contentSha256))
    || result.evidenceSpanIds.some((id) => !UUID_RE.test(id))
    || scienceResearchEpisodeResultSha256(result) !== result.resultSha256) {
    throw new Error("science-research-episode-result-integrity-failed");
  }
  return result;
}

function researchEpisodeFromRow(row: Record<string, unknown>, result: ScienceResearchEpisodeResult | null): ScienceResearchEpisode {
  const expectedObservations = parseTextList(row.expected_observations_json);
  const falsificationCriteria = parseTextList(row.falsification_criteria_json);
  const toolIntents = normalizeResearchEpisodeToolIntents(JSON.parse(String(row.tool_intents_json)));
  const episode: ScienceResearchEpisode = {
    id: String(row.id),
    projectId: String(row.project_id),
    loopSessionId: String(row.loop_session_id),
    ordinal: Number(row.ordinal),
    version: Number(row.version),
    stateSha256: String(row.state_sha256),
    status: String(row.status) as ScienceResearchEpisodeStatus,
    kind: String(row.episode_kind) as ScienceResearchEpisodeKind,
    hypothesisId: String(row.hypothesis_id),
    hypothesisVersion: Number(row.hypothesis_version),
    hypothesisContentSha256: String(row.hypothesis_content_sha256),
    lifecycleStudyId: String(row.lifecycle_study_id),
    lifecycleRevision: Number(row.lifecycle_revision),
    lifecycleStateSha256: String(row.lifecycle_state_sha256),
    objective: String(row.objective),
    method: String(row.method),
    expectedObservations,
    falsificationCriteria,
    toolIntents,
    planSha256: String(row.plan_sha256),
    result,
    startedAt: row.started_at === null || row.started_at === undefined ? null : String(row.started_at),
    finishedAt: row.finished_at === null || row.finished_at === undefined ? null : String(row.finished_at),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
  if (!UUID_RE.test(episode.id) || !UUID_RE.test(episode.projectId) || !UUID_RE.test(episode.loopSessionId)
    || !UUID_RE.test(episode.hypothesisId) || !Number.isSafeInteger(episode.ordinal) || episode.ordinal < 1
    || !Number.isSafeInteger(episode.version) || episode.version < 1 || !SHA256_RE.test(episode.stateSha256)
    || !Number.isSafeInteger(episode.hypothesisVersion) || episode.hypothesisVersion < 1
    || !SHA256_RE.test(episode.hypothesisContentSha256) || !UUID_RE.test(episode.lifecycleStudyId)
    || !Number.isSafeInteger(episode.lifecycleRevision) || episode.lifecycleRevision < 1
    || !SHA256_RE.test(episode.lifecycleStateSha256) || !SHA256_RE.test(episode.planSha256)
    || !["planned", "running", "waiting-for-decision", "succeeded", "failed", "cancelled"].includes(episode.status)
    || !["literature", "simulation", "experiment", "analysis", "verification"].includes(episode.kind)
    || scienceResearchEpisodePlanSha256(episode) !== episode.planSha256
    || scienceResearchEpisodeStateSha256({
      id: episode.id,
      projectId: episode.projectId,
      loopSessionId: episode.loopSessionId,
      ordinal: episode.ordinal,
      version: episode.version,
      status: episode.status,
      kind: episode.kind,
      hypothesisId: episode.hypothesisId,
      hypothesisVersion: episode.hypothesisVersion,
      hypothesisContentSha256: episode.hypothesisContentSha256,
      lifecycleStudyId: episode.lifecycleStudyId,
      lifecycleRevision: episode.lifecycleRevision,
      lifecycleStateSha256: episode.lifecycleStateSha256,
      objective: episode.objective,
      method: episode.method,
      expectedObservations: episode.expectedObservations,
      falsificationCriteria: episode.falsificationCriteria,
      toolIntents: episode.toolIntents,
      planSha256: episode.planSha256,
      resultSha256: episode.result?.resultSha256 ?? null,
      startedAt: episode.startedAt,
      finishedAt: episode.finishedAt,
      createdAt: episode.createdAt,
      updatedAt: episode.updatedAt,
    }) !== episode.stateSha256
    || (["succeeded", "failed", "cancelled"].includes(episode.status) !== (episode.result !== null))) {
    throw new Error("science-research-episode-integrity-failed");
  }
  return episode;
}

function artifactFromRow(row: Record<string, unknown>): ScienceArtifact {
  const rendererBinding = row.renderer_binding_json === null || row.renderer_binding_json === undefined
    ? null
    : normalizeRendererBinding(parseObject(row.renderer_binding_json));
  const artifact: ScienceArtifact = {
    id: String(row.id),
    projectId: String(row.project_id),
    loopSessionId: row.loop_session_id === null || row.loop_session_id === undefined ? null : String(row.loop_session_id),
    sourceRunId: row.source_run_id === null || row.source_run_id === undefined ? null : String(row.source_run_id),
    kind: String(row.kind) as ScienceArtifactKind,
    title: String(row.title),
    status: String(row.status) as ScienceArtifact["status"],
    currentVersion: Number(row.current_version),
    version: {
      id: String(row.version_id),
      artifactId: String(row.id),
      version: Number(row.current_version),
      rendererId: String(row.renderer_id) as ScienceRendererId,
      rendererVersion: String(row.renderer_version),
      rendererBinding,
      payload: parseObject(row.payload_json),
      semantic: parseObject(row.semantic_json) as unknown as ScienceArtifactSemanticSnapshot,
      provenance: parseObject(row.provenance_json) as unknown as ScienceArtifactProvenance,
      contentSha256: String(row.content_sha256),
      createdAt: String(row.version_created_at),
    },
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
  const integrityInput: Record<string, unknown> = {
    kind: artifact.kind,
    title: artifact.title,
    rendererId: artifact.version.rendererId,
    rendererVersion: artifact.version.rendererVersion,
    payload: artifact.version.payload,
    semantic: artifact.version.semantic,
    provenance: artifact.version.provenance,
  };
  if (rendererBinding) integrityInput.rendererBinding = rendererBinding;
  const expected = sha256Json(integrityInput);
  if (expected !== artifact.version.contentSha256) throw new Error("science-artifact-integrity-failed");
  return artifact;
}

function artifactLinkageIntegrityInput(linkage: Omit<ScienceArtifactLinkage, "linkageSha256" | "createdAt">): Record<string, unknown> {
  return {
    schema: linkage.schema,
    projectId: linkage.projectId,
    artifactId: linkage.artifactId,
    artifactVersion: linkage.artifactVersion,
    rendererId: linkage.rendererId,
    labId: linkage.labId,
    origin: linkage.origin,
    parent: linkage.parent,
    inputs: linkage.inputs,
  };
}

function artifactLinkageFromRow(row: Record<string, unknown>): ScienceArtifactLinkage {
  let inputs: unknown = [];
  try { inputs = JSON.parse(String(row.input_refs_json)); } catch { throw new Error("science-artifact-linkage-integrity-failed"); }
  const normalized = normalizeArtifactLinkageInput({
    labId: row.lab_id,
    origin: {
      surface: row.origin_surface,
      conversationId: row.origin_conversation_id,
      messageId: row.origin_message_id,
      loopSessionId: row.origin_loop_session_id,
      runId: row.origin_run_id,
      branchId: row.origin_branch_id,
    },
    parent: row.parent_artifact_id === null || row.parent_artifact_id === undefined ? null : {
      artifactId: row.parent_artifact_id,
      version: Number(row.parent_artifact_version),
    },
    inputs,
  }, String(row.renderer_id) as ScienceRendererId);
  const linkageWithoutDigest: Omit<ScienceArtifactLinkage, "linkageSha256" | "createdAt"> = {
    schema: "agentlas.science-artifact-linkage/v1",
    projectId: String(row.project_id),
    artifactId: String(row.artifact_id),
    artifactVersion: Number(row.artifact_version),
    rendererId: String(row.renderer_id) as ScienceRendererId,
    ...normalized,
  };
  const linkageSha256 = safeSha256(row.linkage_sha256, "artifact-linkage-sha256");
  if (sha256Json(artifactLinkageIntegrityInput(linkageWithoutDigest)) !== linkageSha256) throw new Error("science-artifact-linkage-integrity-failed");
  return { ...linkageWithoutDigest, linkageSha256, createdAt: String(row.created_at) };
}

function conversationArtifactEventFromRow(row: Record<string, unknown>): ScienceConversationArtifactEvent {
  return {
    id: String(row.id),
    projectId: String(row.project_id),
    conversationId: String(row.conversation_id),
    messageId: String(row.message_id),
    turnId: row.origin_turn_id === null || row.origin_turn_id === undefined ? null : String(row.origin_turn_id),
    artifactId: String(row.artifact_id),
    originArtifactVersion: Number(row.origin_artifact_version),
    artifactVersion: Number(row.artifact_version),
    parentArtifactVersion: Number(row.parent_artifact_version),
    labId: String(row.lab_id),
    kind: "version-saved",
    contentSha256: safeSha256(row.content_sha256, "conversation-artifact-event-content-sha256"),
    createdAt: String(row.created_at),
  };
}

function normalizeResearchRunResourceInput(value: unknown, field: string): ScienceResearchRunResourceInput {
  const record = safeJsonRecord(value, 32 * 1024, `run-${field}`);
  const artifactId = record.artifactId === undefined || record.artifactId === null ? null : String(record.artifactId);
  const artifactVersion = record.artifactVersion === undefined || record.artifactVersion === null
    ? null
    : safePositiveInteger(record.artifactVersion, 1, Number.MAX_SAFE_INTEGER, `run-${field}-artifact-version`);
  if ((artifactId === null) !== (artifactVersion === null) || (artifactId !== null && !UUID_RE.test(artifactId))) throw new Error(`science-run-${field}-artifact-invalid`);
  const sha256 = safeSha256(record.sha256, `run-${field}-sha256`);
  const blobRef = safeText(record.blobRef, 2_048, `run-${field}-blob-ref`);
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(blobRef) || !/^science-[a-z-]+:/.test(blobRef) && !/^science-cas:/.test(blobRef)) throw new Error(`science-run-${field}-blob-ref-invalid`);
  return {
    role: safeText(record.role, 160, `run-${field}-role`),
    mimeType: safeText(record.mimeType, 240, `run-${field}-mime-type`),
    byteSize: safePositiveInteger(record.byteSize, 0, 1_099_511_627_776, `run-${field}-byte-size`),
    sha256,
    blobRef,
    artifactId,
    artifactVersion,
  };
}

function researchRunResourceFromRow(row: Record<string, unknown>): ScienceResearchRunResource {
  return {
    id: String(row.id),
    runId: String(row.run_id),
    ordinal: Number(row.ordinal),
    role: String(row.role),
    mimeType: String(row.mime_type),
    byteSize: Number(row.byte_size),
    sha256: safeSha256(row.sha256, "run-resource-sha256"),
    blobRef: String(row.blob_ref),
    artifactId: row.artifact_id === null || row.artifact_id === undefined ? null : String(row.artifact_id),
    artifactVersion: row.artifact_version === null || row.artifact_version === undefined ? null : Number(row.artifact_version),
    createdAt: String(row.created_at),
  };
}

function sourceFigureFromRow(row: Record<string, unknown>): ScienceSourceFigure {
  const figure: ScienceSourceFigure = {
    id: String(row.id),
    projectId: String(row.project_id),
    sourceId: String(row.source_id),
    sourceVersionId: String(row.source_version_id),
    locator: String(row.locator),
    pageNumber: row.page_number === null || row.page_number === undefined ? null : Number(row.page_number),
    figureLabel: String(row.figure_label),
    caption: String(row.caption),
    captionSha256: safeSha256(row.caption_sha256, "source-figure-caption-sha256"),
    mimeType: String(row.mime_type) as ScienceSourceFigure["mimeType"],
    width: Number(row.width),
    height: Number(row.height),
    byteSize: Number(row.byte_size),
    assetSha256: safeSha256(row.asset_sha256, "source-figure-asset-sha256"),
    assetRef: String(row.asset_ref),
    license: row.license === null || row.license === undefined ? null : String(row.license),
    rightsNote: row.rights_note === null || row.rights_note === undefined ? null : String(row.rights_note),
    createdAt: String(row.created_at),
  };
  if (sha256Text(figure.caption) !== figure.captionSha256) throw new Error("science-source-figure-integrity-failed");
  return figure;
}

function validationReceiptIntegrityInput(receipt: Omit<ScienceArtifactValidationReceipt, "id" | "receiptSha256" | "createdAt">): Record<string, unknown> {
  return {
    projectId: receipt.projectId,
    artifactId: receipt.artifactId,
    artifactVersionId: receipt.artifactVersionId,
    artifactVersion: receipt.artifactVersion,
    artifactContentSha256: receipt.artifactContentSha256,
    artifactLinkageSha256: receipt.artifactLinkageSha256,
    visualCaptureId: receipt.visualCaptureId,
    visualAssetSha256: receipt.visualAssetSha256,
    researchRunId: receipt.researchRunId,
    validatorId: receipt.validatorId,
    validatorVersion: receipt.validatorVersion,
    policyId: receipt.policyId,
    policyVersion: receipt.policyVersion,
    status: receipt.status,
    checks: receipt.checks,
    warnings: receipt.warnings,
    challengeSha256: receipt.challengeSha256,
    inputSha256: receipt.inputSha256,
    environmentSha256: receipt.environmentSha256,
  };
}

function validationReceiptFromRow(row: Record<string, unknown>): ScienceArtifactValidationReceipt {
  const unsigned: Omit<ScienceArtifactValidationReceipt, "id" | "receiptSha256" | "createdAt"> = {
    projectId: String(row.project_id),
    artifactId: String(row.artifact_id),
    artifactVersionId: String(row.artifact_version_id),
    artifactVersion: Number(row.artifact_version),
    artifactContentSha256: safeSha256(row.artifact_content_sha256, "validation-artifact-content-sha256"),
    artifactLinkageSha256: safeSha256(row.artifact_linkage_sha256, "validation-artifact-linkage-sha256"),
    visualCaptureId: String(row.visual_capture_id),
    visualAssetSha256: safeSha256(row.visual_asset_sha256, "validation-visual-asset-sha256"),
    researchRunId: String(row.research_run_id),
    validatorId: String(row.validator_id),
    validatorVersion: String(row.validator_version),
    policyId: String(row.policy_id),
    policyVersion: String(row.policy_version),
    status: String(row.status) as ScienceArtifactValidationReceipt["status"],
    checks: parseTextList(row.checks_json),
    warnings: parseTextList(row.warnings_json),
    challengeSha256: safeSha256(row.challenge_sha256, "validation-challenge-sha256"),
    inputSha256: safeSha256(row.input_sha256, "validation-input-sha256"),
    environmentSha256: safeSha256(row.environment_sha256, "validation-environment-sha256"),
  };
  const receiptSha256 = safeSha256(row.receipt_sha256, "validation-receipt-sha256");
  if (sha256Json(validationReceiptIntegrityInput(unsigned)) !== receiptSha256) throw new Error("science-artifact-validation-integrity-failed");
  return { id: String(row.id), ...unsigned, receiptSha256, createdAt: String(row.created_at) };
}

function normalizeManuscriptBindingInput(value: unknown): ScienceManuscriptBindingInput {
  const record = safeJsonRecord(value, 32 * 1024, "manuscript-binding");
  const ordinal = safePositiveInteger(record.ordinal, 1, 100_000, "manuscript-binding-ordinal");
  const role = String(record.role ?? "") as ScienceManuscriptBinding["role"];
  if (!["claim", "citation", "figure", "table", "supplement"].includes(role)) throw new Error("science-manuscript-binding-role-invalid");
  const locator = safeText(record.locator, 2_000, "manuscript-binding-locator");
  const target = record.target;
  if (!target || typeof target !== "object" || Array.isArray(target)) throw new Error("science-manuscript-binding-target-invalid");
  const item = target as Record<string, unknown>;
  if (item.kind === "citation" && UUID_RE.test(String(item.citationId ?? ""))) return { ordinal, role, locator, target: { kind: "citation", citationId: String(item.citationId) } };
  if (item.kind === "source-figure" && UUID_RE.test(String(item.sourceFigureId ?? ""))) return { ordinal, role, locator, target: { kind: "source-figure", sourceFigureId: String(item.sourceFigureId) } };
  if (item.kind === "artifact" && UUID_RE.test(String(item.artifactId ?? "")) && UUID_RE.test(String(item.captureId ?? "")) && UUID_RE.test(String(item.validationReceiptId ?? ""))) {
    return {
      ordinal,
      role,
      locator,
      target: {
        kind: "artifact",
        artifactId: String(item.artifactId),
        artifactVersion: safePositiveInteger(item.artifactVersion, 1, Number.MAX_SAFE_INTEGER, "manuscript-binding-artifact-version"),
        captureId: String(item.captureId),
        validationReceiptId: String(item.validationReceiptId),
      },
    };
  }
  throw new Error("science-manuscript-binding-target-invalid");
}

function manuscriptBindingFromRow(row: Record<string, unknown>): ScienceManuscriptBinding {
  const common = {
    id: String(row.id),
    projectId: String(row.project_id),
    manuscriptVersionId: String(row.manuscript_version_id),
    ordinal: Number(row.ordinal),
    role: String(row.role) as ScienceManuscriptBinding["role"],
    locator: String(row.locator),
    createdAt: String(row.created_at),
  };
  if (row.target_kind === "citation") return { ...common, target: { kind: "citation", citationId: String(row.citation_id) } };
  if (row.target_kind === "source-figure") return { ...common, target: { kind: "source-figure", sourceFigureId: String(row.source_figure_id) } };
  if (row.target_kind === "artifact") {
    return {
      ...common,
      target: {
        kind: "artifact",
        artifactId: String(row.artifact_id),
        artifactVersion: Number(row.artifact_version),
        captureId: String(row.artifact_capture_id),
        validationReceiptId: String(row.validation_receipt_id),
      },
    };
  }
  throw new Error("science-manuscript-binding-integrity-failed");
}

function nullableAnalysisText(value: unknown, maximum: number, field: string): string | null {
  return value === null ? null : safeText(value, maximum, field);
}

function normalizeScienceEstimand(value: unknown): NonNullable<ScienceAnalysisSpecDocument["estimand"]> {
  const record = safeJsonRecord(value, 32 * 1024, "analysis-estimand");
  if (!hasExactKeys(record, ["population", "treatmentOrExposure", "comparator", "outcome", "summaryMeasure", "timeHorizon"])) throw new Error("science-analysis-estimand-invalid");
  return {
    population: safeText(record.population, 2_000, "analysis-estimand-population"),
    treatmentOrExposure: safeText(record.treatmentOrExposure, 2_000, "analysis-estimand-treatment"),
    comparator: nullableAnalysisText(record.comparator, 2_000, "analysis-estimand-comparator"),
    outcome: safeText(record.outcome, 2_000, "analysis-estimand-outcome"),
    summaryMeasure: safeText(record.summaryMeasure, 500, "analysis-estimand-summary-measure"),
    timeHorizon: nullableAnalysisText(record.timeHorizon, 500, "analysis-estimand-time-horizon"),
  };
}

function normalizeScienceDependence(value: unknown): ScienceAnalysisSpecDocument["design"]["dependence"] {
  const record = safeJsonRecord(value, 16 * 1024, "analysis-dependence");
  const kind = String(record.kind ?? "");
  if (kind === "unresolved" || kind === "independent") {
    if (!hasExactKeys(record, ["kind"])) throw new Error("science-analysis-dependence-invalid");
    return { kind };
  }
  if (kind === "repeated") {
    if (!hasExactKeys(record, ["kind", "subjectIdVariable", "timeVariable"])) throw new Error("science-analysis-dependence-invalid");
    return { kind, subjectIdVariable: safeText(record.subjectIdVariable, 240, "analysis-subject-id"), timeVariable: nullableAnalysisText(record.timeVariable, 240, "analysis-time-variable") };
  }
  if (kind === "clustered") {
    if (!hasExactKeys(record, ["kind", "clusterVariables"])) throw new Error("science-analysis-dependence-invalid");
    return { kind, clusterVariables: safeTextList(record.clusterVariables, 16, 240, "analysis-cluster-variable") };
  }
  if (kind === "repeated-and-clustered") {
    if (!hasExactKeys(record, ["kind", "subjectIdVariable", "timeVariable", "clusterVariables"])) throw new Error("science-analysis-dependence-invalid");
    return {
      kind,
      subjectIdVariable: safeText(record.subjectIdVariable, 240, "analysis-subject-id"),
      timeVariable: nullableAnalysisText(record.timeVariable, 240, "analysis-time-variable"),
      clusterVariables: safeTextList(record.clusterVariables, 16, 240, "analysis-cluster-variable"),
    };
  }
  throw new Error("science-analysis-dependence-invalid");
}

function normalizeScienceAnalysisDocument(value: unknown): ScienceAnalysisSpecDocument {
  const record = safeJsonRecord(value, 2 * 1024 * 1024, "analysis-spec");
  const expected = ["schemaVersion", "purpose", "researchQuestion", "population", "estimand", "design", "data", "model", "missingData", "multiplicity", "requiredDiagnostics", "sensitivityAnalyses", "seed", "runtimePolicy", "expectedArtifacts"];
  if (!hasExactKeys(record, expected) || record.schemaVersion !== SCIENCE_ANALYSIS_SPEC_SCHEMA || record.purpose !== "confirmatory") throw new Error("science-analysis-spec-invalid");
  const design = safeJsonRecord(record.design, 64 * 1024, "analysis-design");
  const data = safeJsonRecord(record.data, 512 * 1024, "analysis-data");
  const missingData = safeJsonRecord(record.missingData, 16 * 1024, "analysis-missing-data");
  const multiplicity = safeJsonRecord(record.multiplicity, 16 * 1024, "analysis-multiplicity");
  const seed = safeJsonRecord(record.seed, 4 * 1024, "analysis-seed");
  const runtimePolicy = safeJsonRecord(record.runtimePolicy, 8 * 1024, "analysis-runtime-policy");
  if (!hasExactKeys(design, ["studyType", "experimentalUnit", "observationUnit", "dependence"])) throw new Error("science-analysis-design-invalid");
  if (!hasExactKeys(data, ["inputs", "outcomeVariables", "predictorVariables", "transformations", "exclusions"])) throw new Error("science-analysis-data-invalid");
  if (!hasExactKeys(missingData, ["strategy", "rationale"]) || !["unresolved", "complete-case", "multiple-imputation", "model-based", "not-applicable"].includes(String(missingData.strategy))) throw new Error("science-analysis-missing-data-invalid");
  if (!hasExactKeys(multiplicity, ["strategy", "families", "rationale"]) || !["unresolved", "none", "fdr", "fwer"].includes(String(multiplicity.strategy))) throw new Error("science-analysis-multiplicity-invalid");
  if (!hasExactKeys(seed, ["algorithm", "value"]) || seed.algorithm !== "fixed") throw new Error("science-analysis-seed-invalid");
  if (!hasExactKeys(runtimePolicy, ["network", "maxWallTimeMinutes", "maxCpuCores", "maxRamMb"]) || runtimePolicy.network !== "deny") throw new Error("science-analysis-runtime-policy-invalid");
  const inputsRaw = Array.isArray(data.inputs) ? data.inputs : null;
  if (!inputsRaw || inputsRaw.length > 100) throw new Error("science-analysis-inputs-invalid");
  const inputs = inputsRaw.map((entry) => {
    const item = safeJsonRecord(entry, 8 * 1024, "analysis-input");
    if (!hasExactKeys(item, ["artifactId", "artifactVersion", "contentSha256"]) || !UUID_RE.test(String(item.artifactId ?? ""))) throw new Error("science-analysis-input-invalid");
    return { artifactId: String(item.artifactId), artifactVersion: safePositiveInteger(item.artifactVersion, 1, Number.MAX_SAFE_INTEGER, "analysis-input-version"), contentSha256: safeSha256(item.contentSha256, "analysis-input-content-sha256") };
  });
  if (new Set(inputs.map((item) => `${item.artifactId}:${item.artifactVersion}`)).size !== inputs.length) throw new Error("science-analysis-input-duplicate");
  const studyType = String(design.studyType ?? "") as ScienceAnalysisSpecDocument["design"]["studyType"];
  if (!["randomized-experiment", "observational", "quasi-experiment", "simulation"].includes(studyType)) throw new Error("science-analysis-study-type-invalid");
  let model: ScienceAnalysisSpecDocument["model"] = null;
  if (record.model !== null) {
    const item = safeJsonRecord(record.model, 64 * 1024, "analysis-model");
    if (!hasExactKeys(item, ["family", "formula", "distribution", "link", "groupingVariables", "randomEffects", "rationale"])
      || typeof item.family !== "string"
      || !SCIENCE_ANALYSIS_MODEL_FAMILIES.includes(item.family as NonNullable<ScienceAnalysisSpecDocument["model"]>["family"])) throw new Error("science-analysis-model-invalid");
    model = {
      family: item.family as NonNullable<ScienceAnalysisSpecDocument["model"]>["family"],
      formula: safeText(item.formula, 4_000, "analysis-model-formula"),
      distribution: nullableAnalysisText(item.distribution, 120, "analysis-model-distribution"),
      link: nullableAnalysisText(item.link, 120, "analysis-model-link"),
      groupingVariables: safeTextList(item.groupingVariables, 32, 240, "analysis-model-grouping", 0),
      randomEffects: safeTextList(item.randomEffects, 32, 500, "analysis-model-random-effect", 0),
      rationale: safeText(item.rationale, 8_000, "analysis-model-rationale"),
    };
  }
  const artifactsRaw = Array.isArray(record.expectedArtifacts) ? record.expectedArtifacts : null;
  if (!artifactsRaw || artifactsRaw.length > 32) throw new Error("science-analysis-expected-artifacts-invalid");
  const expectedArtifacts = artifactsRaw.map((entry) => {
    const item = safeJsonRecord(entry, 8 * 1024, "analysis-expected-artifact");
    if (!hasExactKeys(item, ["role", "title"]) || !["result-table", "figure", "diagnostics", "methods"].includes(String(item.role))) throw new Error("science-analysis-expected-artifact-invalid");
    return { role: String(item.role) as ScienceAnalysisSpecDocument["expectedArtifacts"][number]["role"], title: safeText(item.title, 500, "analysis-expected-artifact-title") };
  });
  return {
    schemaVersion: SCIENCE_ANALYSIS_SPEC_SCHEMA,
    purpose: "confirmatory",
    researchQuestion: safeText(record.researchQuestion, 8_000, "analysis-research-question"),
    population: safeText(record.population, 4_000, "analysis-population"),
    estimand: record.estimand === null ? null : normalizeScienceEstimand(record.estimand),
    design: { studyType, experimentalUnit: nullableAnalysisText(design.experimentalUnit, 500, "analysis-experimental-unit"), observationUnit: safeText(design.observationUnit, 500, "analysis-observation-unit"), dependence: normalizeScienceDependence(design.dependence) },
    data: {
      inputs,
      outcomeVariables: safeTextList(data.outcomeVariables, 100, 240, "analysis-outcome-variable"),
      predictorVariables: safeTextList(data.predictorVariables, 200, 240, "analysis-predictor-variable", 0),
      transformations: safeTextList(data.transformations, 200, 2_000, "analysis-transformation", 0),
      exclusions: safeTextList(data.exclusions, 200, 2_000, "analysis-exclusion", 0),
    },
    model,
    missingData: { strategy: String(missingData.strategy) as ScienceAnalysisSpecDocument["missingData"]["strategy"], rationale: safeText(missingData.rationale, 8_000, "analysis-missing-data-rationale") },
    multiplicity: { strategy: String(multiplicity.strategy) as ScienceAnalysisSpecDocument["multiplicity"]["strategy"], families: safeTextList(multiplicity.families, 100, 500, "analysis-multiplicity-family", 0), rationale: safeText(multiplicity.rationale, 8_000, "analysis-multiplicity-rationale") },
    requiredDiagnostics: safeTextList(record.requiredDiagnostics, 100, 500, "analysis-required-diagnostic", 0),
    sensitivityAnalyses: safeTextList(record.sensitivityAnalyses, 100, 2_000, "analysis-sensitivity", 0),
    seed: { algorithm: "fixed", value: safePositiveInteger(seed.value, 0, 2_147_483_647, "analysis-seed") },
    runtimePolicy: { network: "deny", maxWallTimeMinutes: safePositiveInteger(runtimePolicy.maxWallTimeMinutes, 1, 10_080, "analysis-wall-time"), maxCpuCores: safePositiveInteger(runtimePolicy.maxCpuCores, 1, 128, "analysis-cpu-cores"), maxRamMb: safePositiveInteger(runtimePolicy.maxRamMb, 256, 1_048_576, "analysis-ram-mb") },
    expectedArtifacts,
  };
}

function normalizeScienceDecisionDraft(value: unknown): ScienceAnalysisDecisionDraft {
  const record = safeJsonRecord(value, 512 * 1024, "decision-draft");
  const expected = ["decisionKey", "mergeKey", "prompt", "evidenceRefs", "options", "recommendationRationale", "recommendationConfidence", "recommendationAssumptions", "unaffectedNodeIds"];
  if (!hasExactKeys(record, expected) || !["analysis.estimand", "analysis.dependence-structure"].includes(String(record.decisionKey))) throw new Error("science-decision-draft-invalid");
  const decisionKey = String(record.decisionKey) as ScienceAnalysisDecisionDraft["decisionKey"];
  const mergeKey = safeText(record.mergeKey, 200, "decision-merge-key");
  if (!/^[a-z0-9][a-z0-9._:-]{0,199}$/i.test(mergeKey)) throw new Error("science-decision-merge-key-invalid");
  const prompt = safeJsonRecord(record.prompt, 32 * 1024, "decision-prompt");
  if (!hasExactKeys(prompt, ["title", "question", "whyAsked", "impactIfUnanswered"])) throw new Error("science-decision-prompt-invalid");
  const optionsRaw = Array.isArray(record.options) ? record.options : null;
  if (!optionsRaw || optionsRaw.length < 2 || optionsRaw.length > 4) throw new Error("science-decision-options-invalid");
  const options = optionsRaw.map((entry) => {
    const item = safeJsonRecord(entry, 128 * 1024, "decision-option");
    if (!hasExactKeys(item, ["id", "label", "description", "benefits", "risks", "downstreamImpact", "reversible", "recommended", "effect"]) || typeof item.reversible !== "boolean" || typeof item.recommended !== "boolean") throw new Error("science-decision-option-invalid");
    const id = safeText(item.id, 80, "decision-option-id");
    if (!/^[a-z0-9][a-z0-9._-]{0,79}$/i.test(id)) throw new Error("science-decision-option-id-invalid");
    const effectRecord = safeJsonRecord(item.effect, 64 * 1024, "decision-effect");
    let effect: ScienceDecisionOption["effect"];
    if (decisionKey === "analysis.estimand" && effectRecord.kind === "set-estimand" && hasExactKeys(effectRecord, ["kind", "value"])) effect = { kind: "set-estimand", value: normalizeScienceEstimand(effectRecord.value) };
    else if (decisionKey === "analysis.dependence-structure" && effectRecord.kind === "set-dependence" && hasExactKeys(effectRecord, ["kind", "value"])) {
      const dependence = normalizeScienceDependence(effectRecord.value);
      if (dependence.kind === "unresolved") throw new Error("science-decision-effect-invalid");
      effect = { kind: "set-dependence", value: dependence };
    } else throw new Error("science-decision-effect-invalid");
    return { id, label: safeText(item.label, 500, "decision-option-label"), description: safeText(item.description, 4_000, "decision-option-description"), benefits: safeTextList(item.benefits, 20, 2_000, "decision-option-benefit", 0), risks: safeTextList(item.risks, 20, 2_000, "decision-option-risk", 0), downstreamImpact: safeText(item.downstreamImpact, 4_000, "decision-option-impact"), reversible: item.reversible, recommended: item.recommended, effect };
  });
  if (new Set(options.map((option) => option.id)).size !== options.length || options.filter((option) => option.recommended).length !== 1) throw new Error("science-decision-options-invalid");
  const confidence = Number(record.recommendationConfidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error("science-decision-confidence-invalid");
  const evidenceRaw = Array.isArray(record.evidenceRefs) ? record.evidenceRefs : null;
  if (!evidenceRaw || evidenceRaw.length > 50) throw new Error("science-decision-evidence-invalid");
  const evidenceRefs = evidenceRaw.map((entry) => {
    const item = safeJsonRecord(entry, 8 * 1024, "decision-evidence");
    if (item.kind === "analysis-spec-version" && hasExactKeys(item, ["kind"])) return { kind: "analysis-spec-version" } as const;
    if (item.kind === "artifact-version" && hasExactKeys(item, ["kind", "artifactId", "artifactVersion", "contentSha256"]) && UUID_RE.test(String(item.artifactId ?? ""))) return { kind: "artifact-version" as const, artifactId: String(item.artifactId), artifactVersion: safePositiveInteger(item.artifactVersion, 1, Number.MAX_SAFE_INTEGER, "decision-artifact-version"), contentSha256: safeSha256(item.contentSha256, "decision-artifact-sha256") };
    if (item.kind === "evidence-span" && hasExactKeys(item, ["kind", "evidenceSpanId"]) && UUID_RE.test(String(item.evidenceSpanId ?? ""))) return { kind: "evidence-span" as const, evidenceSpanId: String(item.evidenceSpanId) };
    throw new Error("science-decision-evidence-invalid");
  });
  return {
    decisionKey,
    mergeKey,
    prompt: { title: safeText(prompt.title, 500, "decision-title"), question: safeText(prompt.question, 4_000, "decision-question"), whyAsked: safeText(prompt.whyAsked, 8_000, "decision-why"), impactIfUnanswered: safeText(prompt.impactIfUnanswered, 8_000, "decision-unanswered-impact") },
    evidenceRefs,
    options,
    recommendationRationale: safeText(record.recommendationRationale, 8_000, "decision-recommendation-rationale"),
    recommendationConfidence: confidence,
    recommendationAssumptions: safeTextList(record.recommendationAssumptions, 50, 2_000, "decision-recommendation-assumption", 0),
    unaffectedNodeIds: safeTextList(record.unaffectedNodeIds, 100, 240, "decision-unaffected-node", 0),
  };
}

function analysisDecisionPath(key: ScienceAnalysisDecisionDraft["decisionKey"]): "/estimand" | "/design/dependence" {
  return key === "analysis.estimand" ? "/estimand" : "/design/dependence";
}

function analysisValueAtPath(document: ScienceAnalysisSpecDocument, pathValue: "/estimand" | "/design/dependence"): unknown {
  return pathValue === "/estimand" ? document.estimand : document.design.dependence;
}

function normalizedGuidelineText(value: unknown, maximum = 2_000_000, minimum = 80): string {
  const text = safeText(value, maximum, "journal-guideline-text").replace(/\s+/g, " ").trim();
  if (text.length < minimum) throw new Error("science-journal-guideline-text-invalid");
  return text;
}

function normalizeJournalRuleInput(value: unknown): ScienceJournalRuleInput {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("science-journal-rule-invalid");
  const record = value as Record<string, unknown>;
  const id = safeText(record.id, 120, "journal-rule-id").toLowerCase();
  if (!/^[a-z0-9](?:[a-z0-9._-]{0,118}[a-z0-9])?$/.test(id)) throw new Error("science-journal-rule-id-invalid");
  const categories = ["structure", "length", "figures", "references", "ethics", "data-code", "files", "review", "other"] as const;
  const category = String(record.category) as ScienceJournalRuleInput["category"];
  if (!categories.includes(category)) throw new Error("science-journal-rule-category-invalid");
  const severity = String(record.severity) as ScienceJournalRuleInput["severity"];
  if (!["error", "warning", "manual"].includes(severity)) throw new Error("science-journal-rule-severity-invalid");
  const requirement = safeText(record.requirement, 4_000, "journal-rule-requirement");
  const inspectionId = String(record.inspectionId ?? "");
  if (!UUID_RE.test(inspectionId)) throw new Error("science-journal-rule-inspection-invalid");
  const evidenceQuote = normalizedGuidelineText(record.evidenceQuote, 4_000, 20);
  const checkRecord = record.check;
  if (!checkRecord || typeof checkRecord !== "object" || Array.isArray(checkRecord)) throw new Error("science-journal-rule-check-invalid");
  const raw = checkRecord as Record<string, unknown>;
  const kind = String(raw.kind);
  let check: ScienceJournalRuleInput["check"];
  if (kind === "heading-present") {
    check = { kind, headings: safeTextList(raw.headings, 20, 200, "journal-rule-heading"), minimumMatches: safePositiveInteger(raw.minimumMatches, 1, 20, "journal-rule-minimum") };
    if (check.minimumMatches > check.headings.length) throw new Error("science-journal-rule-minimum-invalid");
  } else if (kind === "max-title-characters") {
    check = { kind, maximum: safePositiveInteger(raw.maximum, 1, 10_000, "journal-rule-maximum") };
  } else if (kind === "max-section-words") {
    check = { kind, heading: safeText(raw.heading, 200, "journal-rule-heading"), maximum: safePositiveInteger(raw.maximum, 1, 1_000_000, "journal-rule-maximum") };
  } else if (kind === "max-manuscript-words") {
    check = { kind, maximum: safePositiveInteger(raw.maximum, 1, 2_000_000, "journal-rule-maximum") };
  } else if (kind === "binding-count") {
    const role = String(raw.role) as ScienceManuscriptBinding["role"];
    if (!["claim", "citation", "figure", "table", "supplement"].includes(role)) throw new Error("science-journal-rule-binding-role-invalid");
    const minimum = raw.minimum === undefined ? undefined : safePositiveInteger(raw.minimum, 0, 100_000, "journal-rule-minimum");
    const maximum = raw.maximum === undefined ? undefined : safePositiveInteger(raw.maximum, 0, 100_000, "journal-rule-maximum");
    if (minimum === undefined && maximum === undefined || minimum !== undefined && maximum !== undefined && minimum > maximum) throw new Error("science-journal-rule-binding-count-invalid");
    check = { kind, role, ...(minimum === undefined ? {} : { minimum }), ...(maximum === undefined ? {} : { maximum }) };
  } else if (kind === "required-text") {
    check = { kind, patterns: safeTextList(raw.patterns, 30, 500, "journal-rule-pattern"), minimumMatches: safePositiveInteger(raw.minimumMatches, 1, 30, "journal-rule-minimum") };
    if (check.minimumMatches > check.patterns.length) throw new Error("science-journal-rule-minimum-invalid");
  } else if (kind === "output-format") {
    const allowed = safeTextList(raw.allowed, 4, 10, "journal-rule-output-format") as Array<"docx" | "tex" | "pdf" | "zip">;
    if (allowed.some((item) => !["docx", "tex", "pdf", "zip"].includes(item))) throw new Error("science-journal-rule-output-format-invalid");
    const preferred = String(raw.preferred) as "docx" | "tex" | "pdf";
    if (!["docx", "tex", "pdf"].includes(preferred) || !allowed.includes(preferred)) throw new Error("science-journal-rule-output-format-invalid");
    check = { kind, allowed, preferred };
  } else if (kind === "figure-raster-profile") {
    const minimumDpi = safePositiveInteger(raw.minimumDpi, 300, 600, "journal-rule-figure-dpi");
    if (minimumDpi !== 300 && minimumDpi !== 600) throw new Error("science-journal-rule-figure-dpi-invalid");
    const allowedColorSpaces = safeTextList(raw.allowedColorSpaces, 2, 16, "journal-rule-figure-color-space") as Array<"srgb" | "cmyk">;
    if (allowedColorSpaces.some((item) => item !== "srgb" && item !== "cmyk")) throw new Error("science-journal-rule-figure-color-space-invalid");
    check = { kind, minimumDpi, allowedColorSpaces };
  } else if (kind === "figure-vector-profile") {
    const allowedFormats = safeTextList(raw.allowedFormats, 1, 16, "journal-rule-figure-vector-format") as Array<"svg">;
    if (allowedFormats.some((item) => item !== "svg")) throw new Error("science-journal-rule-figure-vector-format-invalid");
    check = { kind, allowedFormats };
  } else if (kind === "manual-attestation") {
    const code = safeText(raw.code, 120, "journal-rule-attestation").toLowerCase();
    if (!/^[a-z0-9](?:[a-z0-9._-]{0,118}[a-z0-9])?$/.test(code)) throw new Error("science-journal-rule-attestation-invalid");
    check = { kind, code };
  } else {
    throw new Error("science-journal-rule-check-kind-invalid");
  }
  return { id, category, severity, requirement, inspectionId, evidenceQuote, check };
}

function normalizeJournalCoverage(value: unknown): ScienceJournalCoverageEntry[] {
  if (!Array.isArray(value) || value.length !== SCIENCE_JOURNAL_COVERAGE_CATEGORIES.length) throw new Error("science-journal-coverage-incomplete");
  const coverage = value.map((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw new Error("science-journal-coverage-invalid");
    const record = entry as Record<string, unknown>;
    const category = String(record.category) as ScienceJournalCoverageEntry["category"];
    const status = String(record.status) as ScienceJournalCoverageEntry["status"];
    if (!SCIENCE_JOURNAL_COVERAGE_CATEGORIES.includes(category) || !["covered", "not-applicable", "unresolved"].includes(status)) throw new Error("science-journal-coverage-invalid");
    const inspectionId = String(record.inspectionId ?? "");
    if (!UUID_RE.test(inspectionId)) throw new Error("science-journal-coverage-inspection-invalid");
    return {
      category,
      status,
      inspectionId,
      evidenceQuote: normalizedGuidelineText(record.evidenceQuote, 4_000, 20),
      rationale: safeText(record.rationale, 4_000, "journal-coverage-rationale"),
    };
  });
  if (new Set(coverage.map((item) => item.category)).size !== SCIENCE_JOURNAL_COVERAGE_CATEGORIES.length
    || SCIENCE_JOURNAL_COVERAGE_CATEGORIES.some((category) => !coverage.some((item) => item.category === category))) {
    throw new Error("science-journal-coverage-incomplete");
  }
  return coverage.sort((left, right) => SCIENCE_JOURNAL_COVERAGE_CATEGORIES.indexOf(left.category) - SCIENCE_JOURNAL_COVERAGE_CATEGORIES.indexOf(right.category));
}

function normalizeOfficialHosts(value: unknown): string[] {
  const hosts = safeTextList(value, 20, 253, "journal-official-host").map((item) => item.toLowerCase());
  if (new Set(hosts).size !== hosts.length || hosts.some((host) => !/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(host))) {
    throw new Error("science-journal-official-host-invalid");
  }
  return hosts.sort();
}

const SCIENCE_RESEARCH_PHASE_GATE_CODES = new Map<string, string>([
  ["intake->literature", "intake.complete"],
  ["literature->hypothesis", "literature.complete"],
  ["hypothesis->analysis_plan_draft", "hypothesis.complete"],
  ["analysis_plan_draft->analysis_plan_frozen", "analysis_plan.frozen"],
  ["analysis_plan_frozen->execution", "analysis_plan.execution_authorized"],
  ["execution->evidence_reconciliation", "execution.receipts_verified"],
  ["evidence_reconciliation->conclusions", "evidence.reconciled"],
  ["conclusions->manuscript", "conclusions.bounded"],
  ["manuscript->journal_profile", "manuscript.version_bound"],
  ["journal_profile->submission_validation", "journal_profile.verified"],
  ["submission_validation->ready_to_submit", "submission.package_verified"],
]);

function isScienceResearchMainPhase(value: unknown): value is ScienceResearchMainPhase {
  return SCIENCE_RESEARCH_MAIN_PHASES.includes(value as ScienceResearchMainPhase);
}

function normalizeScienceResearchPhase(value: unknown): ScienceResearchLifecyclePhase {
  if (!SCIENCE_RESEARCH_LIFECYCLE_PHASES.includes(value as ScienceResearchLifecyclePhase)) throw new Error("science-research-lifecycle-phase-invalid");
  return value as ScienceResearchLifecyclePhase;
}

function normalizeScienceResearchBlockingDecisions(value: unknown): ScienceResearchBlockingDecision[] {
  if (!Array.isArray(value) || value.length > 100) throw new Error("science-research-lifecycle-decisions-invalid");
  const decisions = value.map((candidate) => {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)
      || !hasExactKeys(candidate as Record<string, unknown>, ["id", "code", "summary", "contentSha256"])) {
      throw new Error("science-research-lifecycle-decision-invalid");
    }
    const record = candidate as Record<string, unknown>;
    const id = String(record.id ?? "");
    if (!UUID_RE.test(id)) throw new Error("science-research-lifecycle-decision-id-invalid");
    const code = safeText(record.code, 120, "research-lifecycle-decision-code").toLowerCase();
    if (!/^[a-z0-9](?:[a-z0-9._-]{0,118}[a-z0-9])?$/.test(code)) throw new Error("science-research-lifecycle-decision-code-invalid");
    return { id, code, summary: safeText(record.summary, 8_000, "research-lifecycle-decision-summary"), contentSha256: safeSha256(record.contentSha256, "research-lifecycle-decision-content-sha256") };
  }).sort((left, right) => left.id.localeCompare(right.id));
  if (new Set(decisions.map((decision) => decision.id)).size !== decisions.length) throw new Error("science-research-lifecycle-decision-duplicate");
  return decisions;
}

function normalizeScienceResearchBlockers(value: unknown): string[] {
  return safeTextList(value, 100, 8_000, "research-lifecycle-blocker", 0).sort();
}

function normalizeScienceResearchFrozenPlan(value: unknown): ScienceResearchFrozenPlanBinding | null {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)
    || !hasExactKeys(value as Record<string, unknown>, ["analysisSpecId", "version", "contentSha256"])) {
    throw new Error("science-research-lifecycle-frozen-plan-invalid");
  }
  const record = value as Record<string, unknown>;
  const analysisSpecId = String(record.analysisSpecId ?? "");
  if (!UUID_RE.test(analysisSpecId)) throw new Error("science-research-lifecycle-frozen-plan-id-invalid");
  return {
    analysisSpecId,
    version: safePositiveInteger(record.version, 1, Number.MAX_SAFE_INTEGER, "research-lifecycle-frozen-plan-version"),
    contentSha256: safeSha256(record.contentSha256, "research-lifecycle-frozen-plan-content-sha256"),
  };
}

function normalizeScienceResearchSubmissionExport(value: unknown): ScienceResearchSubmissionExportBinding | null {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)
    || !hasExactKeys(value as Record<string, unknown>, ["submissionExportId", "packageSha256"])) {
    throw new Error("science-research-lifecycle-submission-export-invalid");
  }
  const record = value as Record<string, unknown>;
  const submissionExportId = String(record.submissionExportId ?? "");
  if (!UUID_RE.test(submissionExportId)) throw new Error("science-research-lifecycle-submission-export-id-invalid");
  return { submissionExportId, packageSha256: safeSha256(record.packageSha256, "research-lifecycle-submission-package-sha256") };
}

function normalizeScienceResearchStop(value: unknown): ScienceResearchStopCondition | null {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)
    || !hasExactKeys(value as Record<string, unknown>, ["code", "reason", "recoveryAction"])) {
    throw new Error("science-research-lifecycle-stop-invalid");
  }
  const record = value as Record<string, unknown>;
  const code = String(record.code ?? "") as ScienceResearchStopCondition["code"];
  if (!SCIENCE_RESEARCH_STOP_CODES.includes(code)) throw new Error("science-research-lifecycle-stop-code-invalid");
  return { code, reason: safeText(record.reason, 8_000, "research-lifecycle-stop-reason"), recoveryAction: safeText(record.recoveryAction, 8_000, "research-lifecycle-stop-recovery") };
}

function normalizeScienceResearchTransitionPreconditions(value: unknown): ScienceResearchLifecycleTransitionPreconditions {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("science-research-lifecycle-preconditions-invalid");
  const record = value as Record<string, unknown>;
  const kind = String(record.kind ?? "") as ScienceResearchLifecycleTransitionPreconditions["kind"];
  if (kind === "state_update") {
    if (!hasExactKeys(record, ["kind", "reason", "evidenceSha256"])) throw new Error("science-research-lifecycle-preconditions-invalid");
    const reason = String(record.reason ?? "") as Extract<ScienceResearchLifecycleTransitionPreconditions, { kind: "state_update" }>["reason"];
    if (!["progress", "decision_opened", "decision_resolved", "blocker_changed"].includes(reason)) throw new Error("science-research-lifecycle-state-update-reason-invalid");
    return { kind, reason, evidenceSha256: safeSha256(record.evidenceSha256, "research-lifecycle-precondition-evidence-sha256") };
  }
  if (kind === "phase_gate") {
    const fromPhase = normalizeScienceResearchPhase(record.fromPhase);
    const toPhase = normalizeScienceResearchPhase(record.toPhase);
    if (!isScienceResearchMainPhase(fromPhase) || !isScienceResearchMainPhase(toPhase)) throw new Error("science-research-lifecycle-phase-gate-invalid");
    const gateCode = safeText(record.gateCode, 120, "research-lifecycle-gate-code");
    if (SCIENCE_RESEARCH_PHASE_GATE_CODES.get(`${fromPhase}->${toPhase}`) !== gateCode) throw new Error("science-research-lifecycle-phase-gate-invalid");
    if (fromPhase === "evidence_reconciliation" && toPhase === "conclusions") {
      if (!hasExactKeys(record, ["kind", "fromPhase", "toPhase", "gateCode", "evidenceSha256", "claimLedgerId", "claimLedgerRevision", "claimLedgerManifestSha256", "claimGateReportSha256", "claimPolicyContentSha256"])) throw new Error("science-research-lifecycle-preconditions-invalid");
      const claimLedgerId = String(record.claimLedgerId ?? "");
      if (!UUID_RE.test(claimLedgerId)) throw new Error("science-research-lifecycle-claim-ledger-id-invalid");
      return { kind, fromPhase, toPhase, gateCode: "evidence.reconciled",
        evidenceSha256: safeSha256(record.evidenceSha256, "research-lifecycle-precondition-evidence-sha256"),
        claimLedgerId,
        claimLedgerRevision: safePositiveInteger(record.claimLedgerRevision, 1, Number.MAX_SAFE_INTEGER, "research-lifecycle-claim-ledger-revision"),
        claimLedgerManifestSha256: safeSha256(record.claimLedgerManifestSha256, "research-lifecycle-claim-ledger-manifest-sha256"),
        claimGateReportSha256: safeSha256(record.claimGateReportSha256, "research-lifecycle-claim-gate-report-sha256"),
        claimPolicyContentSha256: safeSha256(record.claimPolicyContentSha256, "research-lifecycle-claim-policy-sha256"),
      };
    }
    if (!hasExactKeys(record, ["kind", "fromPhase", "toPhase", "gateCode", "evidenceSha256"])) throw new Error("science-research-lifecycle-preconditions-invalid");
    return { kind, fromPhase, toPhase, gateCode, evidenceSha256: safeSha256(record.evidenceSha256, "research-lifecycle-precondition-evidence-sha256") } as ScienceResearchLifecycleTransitionPreconditions;
  }
  if (kind === "block" || kind === "stop" || kind === "fail") {
    if (!hasExactKeys(record, ["kind", "fromPhase", "evidenceSha256"])) throw new Error("science-research-lifecycle-preconditions-invalid");
    const fromPhase = normalizeScienceResearchPhase(record.fromPhase);
    if ((kind === "block" && !isScienceResearchMainPhase(fromPhase))
      || (kind !== "block" && !(isScienceResearchMainPhase(fromPhase) || fromPhase === "blocked"))) {
      throw new Error("science-research-lifecycle-terminal-precondition-invalid");
    }
    return { kind, fromPhase, evidenceSha256: safeSha256(record.evidenceSha256, "research-lifecycle-precondition-evidence-sha256") } as ScienceResearchLifecycleTransitionPreconditions;
  }
  if (kind === "resume") {
    if (!hasExactKeys(record, ["kind", "resumePhase", "resolutionSha256"])) throw new Error("science-research-lifecycle-preconditions-invalid");
    const resumePhase = normalizeScienceResearchPhase(record.resumePhase);
    if (!isScienceResearchMainPhase(resumePhase)) throw new Error("science-research-lifecycle-resume-phase-invalid");
    return { kind, resumePhase, resolutionSha256: safeSha256(record.resolutionSha256, "research-lifecycle-resolution-sha256") };
  }
  throw new Error("science-research-lifecycle-preconditions-kind-invalid");
}

function scienceResearchLifecycleStatus(phase: ScienceResearchLifecyclePhase, openDecisionCount: number): ScienceResearchLifecycleStatus {
  if (phase === "blocked") return "blocked";
  if (phase === "stopped") return "stopped";
  if (phase === "failed") return "failed";
  if (phase === "ready_to_submit") return "complete";
  return openDecisionCount > 0 ? "waiting_for_decision" : "active";
}

function scienceResearchLifecycleStateHash(input: {
  studyId: string;
  projectId: string;
  revision: number;
  previousRevision: number | null;
  previousStateSha256: string | null;
  previousContentSha256: string | null;
  contentSha256: string;
  createdAt: string;
}): string {
  return sha256Json({ schema: SCIENCE_RESEARCH_LIFECYCLE_SCHEMA, ...input });
}

